package com.discordnotifications;

import com.google.common.base.Strings;
import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.RuneLite;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.DrawManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import java.util.stream.Collectors;

@Slf4j
@Singleton
public class DiscordWebhookService
{
	static final int MAX_CONTENT_LENGTH = 2_000;
	private static final String ELLIPSIS = "\u2026";
	private static final long CAPTURE_TIMEOUT_MS = 2_000;
	private static final MediaType PNG = MediaType.parse("image/png");
	private static final MediaType JPEG = MediaType.parse("image/jpeg");
	private static final int MAX_RETRIES = 3;
	private static final long RETRY_BASE_DELAY_MS = 2_000;
	private static final long MAX_RETRY_DELAY_MS = 60_000;
	private static final long TIMEOUT_SECONDS = 15;
	private static final long IMAGE_WRITE_TIMEOUT_SECONDS = 30;
	// build.gradle doesn't ship, so the real plugin version isn't available at runtime
	private static final String USER_AGENT = RuneLite.USER_AGENT + " (DiscordNotifications/1.x)";

	private OkHttpClient httpClient;

	@Inject
	private DrawManager drawManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private DiscordNotificationsConfig config;

	@Inject
	private ClientThread clientThread;

	@Inject
	private Client client;

	@Inject
	private Gson gson;

	private NotificationQueue queue;

	@Inject
	private void configureHttpClient(OkHttpClient okHttpClient)
	{
		httpClient = okHttpClient.newBuilder()
			.connectTimeout(TIMEOUT_SECONDS, TimeUnit.SECONDS)
			.readTimeout(TIMEOUT_SECONDS, TimeUnit.SECONDS)
			.build();
	}

	@Inject
	private void connectQueue(NotificationQueue queue)
	{
		this.queue = queue;
		queue.connect(this::captureScreenshot, this::postToAll);
	}

	public void send(Notification notification)
	{
		List<String> urls = resolveWebhookUrls(overrideFor(notification.getType()), config.webhook());
		if (urls.isEmpty())
		{
			return;
		}

		queue.add(urls, notification);
	}

	private String overrideFor(NotificationType type)
	{
		switch (type)
		{
			case PET:
				return config.petWebhook();
			case COLLECTION_LOG:
			case COLLECTION_LOG_RANK:
				return config.collectionLogWebhook();
			case LOOT:
				return config.lootWebhook();
			case KILL_COUNT:
				return config.killCountWebhook();
			case COMBAT_ACHIEVEMENT:
				return config.combatAchievementWebhook();
			case DIARY:
				return config.diaryWebhook();
			case LEAGUES:
				return config.leaguesWebhook();
			case CLUE:
				return config.clueWebhook();
			case QUEST:
				return config.questWebhook();
			case LEVEL:
				return config.levelWebhook();
			case DEATH:
				return config.deathWebhook();
			default:
				return null;
		}
	}

	// An override with no usable URL in it counts as blank, a typo shouldn't lose the message
	static List<String> resolveWebhookUrls(String override, String primary)
	{
		List<String> urls = parseWebhookUrls(override);
		return urls.isEmpty() ? parseWebhookUrls(primary) : urls;
	}

	static List<String> parseWebhookUrls(String configured)
	{
		if (Strings.isNullOrEmpty(configured))
		{
			return Collections.emptyList();
		}

		return WildcardList.entries(configured, "[\\s,;]")
			.map(HttpUrl::parse)
			.filter(Objects::nonNull)
			.map(HttpUrl::toString)
			.collect(Collectors.toList());
	}

	private void captureScreenshot(Consumer<byte[]> onImage)
	{
		AtomicBoolean delivered = new AtomicBoolean();
		// Client thread only
		List<Integer> hidden = new ArrayList<>();

		// DrawManager drops its listeners without a word when it can't draw (minimised, loading screen)
		executor.schedule(() ->
		{
			if (delivered.compareAndSet(false, true))
			{
				log.debug("No frame within {}ms, sending without a screenshot", CAPTURE_TIMEOUT_MS);
				clientThread.invoke(() -> unhideWidgets(hidden));
				onImage.accept(null);
			}
		}, CAPTURE_TIMEOUT_MS, TimeUnit.MILLISECONDS);

		// Tick end so the popup or chat line that caused this is on screen
		clientThread.invokeAtTickEnd(() ->
		{
			// After the timeout nothing would unhide these
			if (delivered.get())
			{
				return;
			}

			hideChat(hidden);
			drawManager.requestNextFrameListener(image ->
			{
				if (!delivered.compareAndSet(false, true))
				{
					return;
				}
				clientThread.invoke(() -> unhideWidgets(hidden));
				executor.execute(() -> onImage.accept(ScreenshotEncoder.encode(image)));
			});
		});
	}

	private void hideChat(List<Integer> hidden)
	{
		ChatPrivacy privacy = config.chatPrivacy();
		if (privacy != ChatPrivacy.SHOW_ALL)
		{
			hideWidget(InterfaceID.PmChat.CONTAINER, hidden);
		}
		if (privacy == ChatPrivacy.HIDE_ALL)
		{
			hideWidget(InterfaceID.Chatbox.CHATAREA, hidden);
		}
	}

	private void hideWidget(int component, List<Integer> hidden)
	{
		Widget widget = client.getWidget(component);
		if (widget != null && !widget.isHidden())
		{
			widget.setHidden(true);
			hidden.add(component);
		}
	}

	private void unhideWidgets(List<Integer> hidden)
	{
		for (int component : hidden)
		{
			Widget widget = client.getWidget(component);
			if (widget != null)
			{
				widget.setHidden(false);
			}
		}
	}

	static String truncate(String text)
	{
		if (text.length() <= MAX_CONTENT_LENGTH)
		{
			return text;
		}

		// Newlines count too, a batched post has one event per line
		int limit = MAX_CONTENT_LENGTH - ELLIPSIS.length();
		int cut = Math.max(text.lastIndexOf(' ', limit), text.lastIndexOf('\n', limit));
		return text.substring(0, cut > 0 ? cut : limit) + ELLIPSIS;
	}

	private void postToAll(List<String> urls, String text, byte[] image)
	{
		DiscordWebhookBody body = new DiscordWebhookBody();
		body.setContent(truncate(text));
		String payload = gson.toJson(body);

		boolean jpeg = ScreenshotEncoder.isJpeg(image);
		RequestBody imageBody = image == null ? null : RequestBody.create(jpeg ? JPEG : PNG, image);
		OkHttpClient client = imageBody == null ? httpClient : httpClient.newBuilder()
			.writeTimeout(IMAGE_WRITE_TIMEOUT_SECONDS, TimeUnit.SECONDS)
			.build();

		for (String url : urls)
		{
			MultipartBody.Builder builder = new MultipartBody.Builder()
				.setType(MultipartBody.FORM)
				.addFormDataPart("payload_json", payload);

			if (imageBody != null)
			{
				builder.addFormDataPart("file", jpeg ? "image.jpg" : "image.png", imageBody);
			}

			Request request = new Request.Builder()
				.url(url)
				.header("User-Agent", USER_AGENT)
				.post(builder.build())
				.build();

			sendRequest(client, request, 0);
		}
	}

	private void sendRequest(OkHttpClient client, Request request, int attempt)
	{
		client.newCall(request).enqueue(
			new Callback()
			{
				@Override
				public void onFailure(Call call, IOException e)
				{
					retryOrGiveUp(client, request, attempt, e.toString(), null);
				}

				@Override
				public void onResponse(Call call, Response response)
				{
					response.close();
					int code = response.code();
					if (response.isSuccessful())
					{
						return;
					}

					if (code >= 400 && code < 500 && code != 429)
					{
						log.warn("Webhook rejected: HTTP {}", code);
						return;
					}

					retryOrGiveUp(client, request, attempt, "HTTP " + code, response.header("Retry-After"));
				}
			}
		);
	}

	private void retryOrGiveUp(OkHttpClient client, Request request, int attempt, String reason, String retryAfter)
	{
		long delay = retryDelayMs(retryAfter, attempt);

		// Don't log the request, the webhook URL is a secret
		if (attempt >= MAX_RETRIES || delay > MAX_RETRY_DELAY_MS)
		{
			log.warn("Webhook failed after {} retries: {}", attempt, reason);
			return;
		}

		log.debug("Webhook failed, retrying in {}ms: {}", delay, reason);
		executor.schedule(() -> sendRequest(client, request, attempt + 1), delay, TimeUnit.MILLISECONDS);
	}

	// Seconds only, an HTTP-date falls back to the normal backoff
	static long retryDelayMs(String retryAfter, int attempt)
	{
		long backoff = RETRY_BASE_DELAY_MS << attempt;
		if (retryAfter == null)
		{
			return backoff;
		}

		try
		{
			double seconds = Double.parseDouble(retryAfter.trim());
			return seconds >= 0 ? (long) Math.ceil(seconds * 1000) : backoff;
		}
		catch (NumberFormatException e)
		{
			return backoff;
		}
	}
}

package com.discordnotifications;

import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.events.ConfigChanged;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.List;

@Singleton
public class GameSettingsWarning
{
	private static final String CONFIG_GROUP = "discordnotifications";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private DiscordNotificationsConfig config;

	@Inject
	private ChatMessageManager chatMessageManager;

	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.SETTINGS)
		{
			warn(config.includeCollectionLogs(), config.includePets(), readsKillCounts(), config.includeCombatAchievements());
		}
	}

	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()) || !"true".equals(event.getNewValue()) || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		String key = event.getKey();
		boolean collectionLog = key.equals("includeCollectionLogs");
		boolean pets = key.equals("includePets");
		boolean killCountFilter = collectionLog || pets || key.equals("includeLoot") || key.equals("includeKillCounts");
		boolean combatAchievements = key.equals("includeCombatAchievements");
		// Config changes don't arrive on the client thread
		clientThread.invokeLater(() -> warn(collectionLog, pets, killCountFilter, combatAchievements));
	}

	public void onVarbitChanged(VarbitChanged event)
	{
		int id = event.getVarbitId();
		boolean collectionLog = id == VarbitID.OPTION_COLLECTION_NEW_ITEM && config.includeCollectionLogs();
		boolean pets = (id == VarbitID.OPTION_LOOTNOTIFICATION_ON || id == VarbitID.OPTION_LOOTNOTIFICATION_UNTRADEABLES) && config.includePets();
		boolean killCountFilter = id == VarbitID.BOSS_KILLCOUNT_FILTERED && readsKillCounts();
		boolean combatAchievements = id == VarbitID.CA_TASK_RECOMPLETION_NOTIFICATIONS && config.includeCombatAchievements();

		if ((collectionLog || pets || killCountFilter || combatAchievements) && WorldUtils.isVisible(client, InterfaceID.Settings.UNIVERSE))
		{
			warn(collectionLog, pets, killCountFilter, combatAchievements);
		}
	}

	private boolean readsKillCounts()
	{
		return config.includeLoot() || config.includePets() || config.includeCollectionLogs() || config.includeKillCounts();
	}

	private void warn(boolean collectionLog, boolean pets, boolean killCountFilter, boolean combatAchievements)
	{
		List<String> problems = new ArrayList<>();
		if (collectionLog && client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) == 0)
		{
			problems.add("Turn on Collection log - New addition notification or new log slots won't post.");
		}
		if (pets && (client.getVarbitValue(VarbitID.OPTION_LOOTNOTIFICATION_ON) == 0 || client.getVarbitValue(VarbitID.OPTION_LOOTNOTIFICATION_UNTRADEABLES) == 0))
		{
			problems.add("Turn on Loot drop notifications and Untradeable loot notifications or pets can post without a name.");
		}
		if (killCountFilter && client.getVarbitValue(VarbitID.BOSS_KILLCOUNT_FILTERED) > 0)
		{
			problems.add("Turn off Filter out boss kill-count with spam-filter or kill counts can be missing from posts.");
		}
		if (combatAchievements && client.getVarbitValue(VarbitID.CA_TASK_RECOMPLETION_NOTIFICATIONS) > 0)
		{
			problems.add("Turn off Combat Achievement Tasks - Repeat completion or repeated tasks will post again.");
		}

		if (!problems.isEmpty())
		{
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage("Discord Notifications: " + String.join(" ", problems))
				.build());
		}
	}
}

package com.discordnotifications;

import lombok.Value;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.QuantityFormatter;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Collection;
import java.util.stream.Collectors;

@Singleton
public class ItemStackFormatter
{
	@Inject
	private ItemManager itemManager;

	public Stack stackWithStorePrice(int itemId, int quantity)
	{
		ItemComposition item = itemManager.getItemComposition(itemId);
		long price = inferredPrice(itemId);
		if (price <= 0)
		{
			price = itemManager.getItemPrice(itemId);
		}
		return new Stack(item.getMembersName(), quantity, price > 0 ? price : item.getPrice());
	}

	// Untradeable drops whose store price says nothing about what they're worth
	private long inferredPrice(int itemId)
	{
		switch (itemId)
		{
			case ItemID.ARAXYTE_FANG:
				return gePrice(ItemID.ETCHED_ARAXYTE_FANG);
			case ItemID.ELDER_VENATOR_FANG:
				return gePrice(ItemID.ETCHED_ELDER_VENATOR_FANG);
			case ItemID.NOXIOUS_HALBERD_PART_1:
			case ItemID.NOXIOUS_HALBERD_PART_2:
			case ItemID.NOXIOUS_HALBERD_PART_3:
				return gePrice(ItemID.NOXIOUS_HALBERD) / 3;
			case ItemID.MOKHAIOTL_CLOTH:
				return gePrice(ItemID.CONFLICTION_GAUNTLETS) - gePrice(ItemID.ZENYTE_BRACELET_ENCHANTED) - gePrice(ItemID.DEMON_TEAR) * 10_000;
			default:
				return 0;
		}
	}

	private long gePrice(int itemId)
	{
		return itemManager.getItemPriceWithSource(itemId, true);
	}

	public static String format(Collection<Stack> stacks)
	{
		return stacks.stream().map(ItemStackFormatter::format).collect(Collectors.joining(", "));
	}

	public static String format(Stack stack)
	{
		String text = QuantityFormatter.formatNumber(stack.getQuantity()) + " x " + stack.getName();
		return stack.getTotalPrice() > 0 ? text + " (" + QuantityFormatter.quantityToStackSize(stack.getTotalPrice()) + ")" : text;
	}

	public static long totalValue(Collection<Stack> stacks)
	{
		return stacks.stream().mapToLong(Stack::getTotalPrice).sum();
	}

	@Value
	public static class Stack
	{
		String name;
		int quantity;
		long unitPrice;

		public long getTotalPrice()
		{
			return unitPrice * quantity;
		}
	}
}

package com.discordnotifications;

import com.discordnotifications.BossNames.BossKc;
import com.discordnotifications.NpcLootPairing.Signal;
import com.google.common.collect.ImmutableMap;
import lombok.Getter;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.NPCComposition;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.http.api.loottracker.LootRecordType;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.Duration;
import java.time.Instant;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

import static com.discordnotifications.BossNames.BOSS_VARPS;
import static com.discordnotifications.BossNames.CG_BOSS;
import static com.discordnotifications.BossNames.CG_NAME;
import static com.discordnotifications.BossNames.COX;
import static com.discordnotifications.BossNames.GAUNTLET_BOSS;
import static com.discordnotifications.BossNames.RAIDS;
import static com.discordnotifications.BossNames.THE_GAUNTLET;
import static com.discordnotifications.BossNames.cleanBossName;
import static com.discordnotifications.BossNames.parseBoss;

@Singleton
public class KillCountService
{
	private static final String CONFIG_GROUP = "discordnotifications";
	private static final int SLAYER_LOG_CAP = 65535;
	private static final Duration RECENT_DROP = Duration.ofSeconds(30);
	// PetNotifier can wait 3.6 s for the pet name before it asks for the drop
	private static final Duration RECENT_PET_DROP = Duration.ofSeconds(6);

	// Core posts LootReceived for these instead of NpcLootReceived
	public static final Set<String> LOOT_RECEIVED_NPCS = Set.of("The Whisperer", "Araxxor", "Branda the Fire Queen", "Eldric the Ice King", GAUNTLET_BOSS, CG_BOSS);

	private static final Pattern PICKPOCKET = Pattern.compile("You pick (the )?.+'s? pocket.*");

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private CoreKillCounts coreKillCounts;

	@Inject
	private NpcLootPairing npcLootPairing;

	private final Map<String, Integer> counts = new HashMap<>();

	@Getter
	private Drop lastDrop;

	private int pickpocketTick = -1;

	public void reset()
	{
		counts.clear();
		lastDrop = null;
		pickpocketTick = -1;
		npcLootPairing.reset();
	}

	public boolean onNpcLootReceived(NpcLootReceived event)
	{
		return recordNpcLoot(event.getNpc().getName(), event.getItems(), Signal.TILE_SCAN);
	}

	// Core posts this for pickpockets too and drops them the same way, the loot tracker reports those
	public boolean onServerNpcLoot(ServerNpcLoot event)
	{
		NPCComposition npc = event.getComposition();
		return npc != null && client.getTickCount() != pickpocketTick && recordNpcLoot(npc.getName(), event.getItems(), Signal.SERVER);
	}

	private boolean recordNpcLoot(String name, Collection<ItemStack> items, Signal signal)
	{
		if (name == null || LOOT_RECEIVED_NPCS.contains(name) || !npcLootPairing.isNewKill(name, items, signal, Instant.now()))
		{
			return false;
		}

		recordLoot(LootRecordType.NPC, name, items);
		return true;
	}

	public void notePickpocket(String message)
	{
		if (PICKPOCKET.matcher(message).matches())
		{
			pickpocketTick = client.getTickCount();
		}
	}

	public void onPlayerLootReceived(PlayerLootReceived event)
	{
		String name = event.getPlayer().getName();
		if (name != null)
		{
			recordLoot(LootRecordType.PLAYER, name, event.getItems());
		}
	}

	public void onLootReceived(LootReceived event)
	{
		LootRecordType type = event.getType();
		// Core's empty Maggot King posts, popping an egg after the kill isn't another kill
		if (type == LootRecordType.UNKNOWN || event.getName() == null)
		{
			return;
		}

		// The loot tracker reposts every NPC and PvP kill, those are already counted above
		if (type == LootRecordType.PLAYER || (type == LootRecordType.NPC && !LOOT_RECEIVED_NPCS.contains(event.getName())))
		{
			return;
		}

		String source = getStandardizedSource(event);
		recordLoot(standardizedType(source, type), source, event.getItems());
	}

	public BossKc onGameMessage(String message)
	{
		notePickpocket(message);

		CompletedClue clue = CompletedClue.parse(message);
		if (clue != null)
		{
			recordChatCount("Clue Scroll (" + clue.getTier() + ")", clue.getCount());
			return null;
		}

		BossKc parsed = parseBoss(message);
		if (parsed == null)
		{
			return null;
		}

		String boss = parsed.getBoss();
		recordChatCount(boss, parsed.getCount());
		if (boss.equals("Araxxor") || boss.equals("Maggot King") || boss.endsWith("Gauntlet") || RAIDS.stream().anyMatch(boss::startsWith))
		{
			// These give their loot late or not through the NPC event, so pets and clog need the name now
			lastDrop = new Drop(boss, LootRecordType.EVENT, Collections.emptyList(), Instant.now());
		}
		return parsed;
	}

	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.KILL_LOG)
		{
			clientThread.invokeAtTickEnd(this::readSlayerLog);
		}
	}

	public String getStandardizedSource(LootReceived event)
	{
		String name = event.getName();
		if (GAUNTLET_BOSS.equals(name))
		{
			return THE_GAUNTLET;
		}
		if (CG_BOSS.equals(name))
		{
			return CG_NAME;
		}

		// Raid loot is just "Chambers of Xeric", the chat line has the mode
		boolean sameRaid = lastDrop != null && event.getType() == LootRecordType.EVENT
			&& RAIDS.stream().anyMatch(raid -> raid.equals(name) && lastDrop.getSource().startsWith(raid));
		return sameRaid ? lastDrop.getSource() : name;
	}

	public static LootRecordType standardizedType(String source, LootRecordType type)
	{
		return THE_GAUNTLET.equals(source) || CG_NAME.equals(source) ? LootRecordType.EVENT : type;
	}

	public boolean lootTrackerDisabled()
	{
		return coreKillCounts.lootTrackerDisabled();
	}

	public Integer getKillCount(LootRecordType type, String source)
	{
		if (source == null)
		{
			return null;
		}

		int kc = Math.max(storedKc(type, source, 0), counts.getOrDefault(cacheKey(type, source), 0));
		return kc > 0 ? kc : null;
	}

	public Drop getRecentDrop()
	{
		return isRecent(lastDrop, Instant.now()) || heldForCoxChest() ? lastDrop : null;
	}

	static boolean isRecent(Drop drop, Instant now)
	{
		return drop != null && Duration.between(drop.getTime(), now).compareTo(RECENT_DROP) <= 0;
	}

	public Drop getRecentPetDrop()
	{
		return isRecentForPet(lastDrop, Instant.now()) || heldForCoxChest() ? lastDrop : null;
	}

	// EVENT keeps the long window, raid chests pay out well after the drop is recorded
	static boolean isRecentForPet(Drop drop, Instant now)
	{
		return isRecent(drop, now)
			&& (drop.getType() == LootRecordType.EVENT || Duration.between(drop.getTime(), now).compareTo(RECENT_PET_DROP) <= 0);
	}

	private boolean heldForCoxChest()
	{
		return isAwaitingCoxChest(lastDrop) && client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1;
	}

	// The chest can sit unopened for minutes after the KC line, and only that line records no items
	static boolean isAwaitingCoxChest(Drop drop)
	{
		return drop != null && drop.getType() == LootRecordType.EVENT && drop.getItems().isEmpty() && drop.getSource().startsWith(COX);
	}

	public static Map<String, String> sourcePlaceholders(String source, Integer kc)
	{
		return ImmutableMap.of("source", source, "from", " from " + source, "kc", kcText(kc));
	}

	public static String kcText(Integer kc)
	{
		return kc == null ? "" : " (KC " + QuantityFormatter.formatNumber(kc) + ")";
	}

	private void recordLoot(LootRecordType type, String source, Collection<ItemStack> items)
	{
		lastDrop = new Drop(source, type, items, Instant.now());

		// Don't start counting from nothing, a made up "KC 1" is worse than no KC
		Integer kc = counts.compute(cacheKey(type, source), (key, cached) ->
		{
			if (cached != null)
			{
				return cached + 1;
			}
			int stored = storedKc(type, source, 1);
			return stored > 0 ? stored + 1 : null;
		});

		if (kc != null && type == LootRecordType.NPC && savedKc(source) > 0)
		{
			saveKc(source, kc);
		}
	}

	// Chat can land either side of the loot event: cached is kc - 1 until the bump, saved is exact
	private void recordChatCount(String source, int kc)
	{
		counts.merge(cacheKey(LootRecordType.UNKNOWN, source), kc - 1, Math::max);
		saveKc(source, kc);
	}

	// lootOffset is 1 while handling a loot event, the game's own counts may already include that kill
	private int storedKc(LootRecordType type, String source, int lootOffset)
	{
		int kc = coreKillCounts.lootTrackerKills(type, source);
		if (type == LootRecordType.PLAYER || type == LootRecordType.PICKPOCKET)
		{
			return kc;
		}

		String boss = cleanBossName(source);
		Integer varp = BOSS_VARPS.get(boss);
		kc = Math.max(kc, savedKc(source));
		kc = Math.max(kc, coreKillCounts.chatCommandsKc(boss) - lootOffset);
		return varp == null ? kc : Math.max(kc, client.getVarpValue(varp) - lootOffset);
	}

	public Double getPb(String boss)
	{
		return coreKillCounts.chatCommandsPb(cleanBossName(boss));
	}

	private int savedKc(String source)
	{
		Integer kc = configManager.getRSProfileConfiguration(CONFIG_GROUP, savedKey(source), int.class);
		return kc == null ? 0 : kc;
	}

	private void saveKc(String source, int kc)
	{
		if (kc > savedKc(source))
		{
			configManager.setRSProfileConfiguration(CONFIG_GROUP, savedKey(source), kc);
		}
	}

	private void readSlayerLog()
	{
		Widget title = client.getWidget(InterfaceID.KillLog.INTERFACE_TITLE);
		Widget names = client.getWidget(InterfaceID.KillLog.NAME);
		Widget kills = client.getWidget(InterfaceID.KillLog.KILL);
		if (title == null || names == null || kills == null || !"Slayer Kill Log".equals(title.getText()))
		{
			return;
		}

		Widget[] mobs = names.getChildren();
		Widget[] values = kills.getChildren();
		if (mobs == null || values == null)
		{
			return;
		}

		for (int i = 0; i < Math.min(mobs.length, values.length); i++)
		{
			saveKc(mobs[i].getText().replace(":", ""), parseSlayerCount(values[i].getText()));
		}
	}

	static int parseSlayerCount(String text)
	{
		String count = text.replace(",", "").trim();
		if (count.startsWith("Lots"))
		{
			return SLAYER_LOG_CAP;
		}

		try
		{
			return Integer.parseInt(count);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	private static String cacheKey(LootRecordType type, String source)
	{
		if (type == LootRecordType.PLAYER || type == LootRecordType.PICKPOCKET)
		{
			return type + "_" + source;
		}
		return cleanBossName(source);
	}

	private static String savedKey(String source)
	{
		return "kc_" + cleanBossName(source);
	}

	@Value
	public static class Drop
	{
		String source;
		LootRecordType type;
		Collection<ItemStack> items;
		Instant time;
	}
}

package com.discordnotifications;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public enum LeagueTaskTier
{
	EASY("Easy", 10),
	MEDIUM("Medium", 30),
	HARD("Hard", 80),
	ELITE("Elite", 200),
	MASTER("Master", 400);

	private final String displayName;
	@Getter
	private final int points;

	public static LeagueTaskTier fromName(String name)
	{
		for (LeagueTaskTier tier : values())
		{
			if (tier.displayName.equalsIgnoreCase(name))
			{
				return tier;
			}
		}
		return null;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.discordnotifications;

import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public enum LootValueBasis
{
	ITEM("Single item"),
	STACK("Whole stack"),
	DROP("Whole drop");

