package com.discordnotifications;

import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import java.util.stream.Collectors;

@Slf4j
@Singleton
class NotificationQueue
{
	private static final long WINDOW_MS = 3_000;
	private static final long SWEEP_INTERVAL_MS = 500;
	// PetNotifier can hold a pet for 6 game ticks, the clog line has to still be here when it lands
	private static final long COLLECTION_LOG_WINDOW_MS = 4_500;
	private static final String NEW_ENTRY_NOTE = " (new collection log entry!)";

	interface Poster
	{
		void post(List<String> urls, String text, byte[] image);
	}

	private final ScheduledExecutorService executor;
	private final Map<List<String>, Batch> batches = new LinkedHashMap<>();

	private Consumer<Consumer<byte[]>> capture;
	private Poster poster;
	private ScheduledFuture<?> sweepTask;

	@Inject
	NotificationQueue(ScheduledExecutorService executor)
	{
		this.executor = executor;
	}

	void connect(Consumer<Consumer<byte[]>> capture, Poster poster)
	{
		this.capture = capture;
		this.poster = poster;
	}

	synchronized void start()
	{
		if (sweepTask != null)
		{
			return;
		}

		sweepTask = executor.scheduleAtFixedRate(() ->
		{
			// scheduleAtFixedRate cancels the task for good if it throws
			try
			{
				sweep();
			}
			catch (Exception e)
			{
				log.warn("Notification sweep failed", e);
			}
		}, SWEEP_INTERVAL_MS, SWEEP_INTERVAL_MS, TimeUnit.MILLISECONDS);
	}

	synchronized void shutdown()
	{
		if (sweepTask != null)
		{
			sweepTask.cancel(false);
			sweepTask = null;
		}

		batches.values().forEach(this::post);
		batches.clear();
	}

	synchronized void add(List<String> urls, Notification notification)
	{
		long now = now();
		Batch batch = batches.computeIfAbsent(urls, u -> new Batch(u, now + WINDOW_MS));
		batch.notifications.add(notification);

		if (notification.getType() == NotificationType.COLLECTION_LOG)
		{
			batch.deadline = Math.max(batch.deadline, now + COLLECTION_LOG_WINDOW_MS);
		}

		if (notification.isScreenshot() && !batch.captureRequested)
		{
			batch.captureRequested = true;
			capture.accept(image -> onCaptured(batch, image));
		}
	}

	private synchronized void onCaptured(Batch batch, byte[] image)
	{
		batch.image = image;
		batch.captureDone = true;
	}

	private synchronized void sweep()
	{
		long now = now();
		for (Iterator<Batch> it = batches.values().iterator(); it.hasNext(); )
		{
			Batch batch = it.next();
			// The capture has its own timeout so this can't hold a batch forever
			if (now >= batch.deadline && (!batch.captureRequested || batch.captureDone))
			{
				it.remove();
				post(batch);
			}
		}
	}

	// Tests override this so the windows don't have to really pass
	long now()
	{
		return System.currentTimeMillis();
	}

	private void post(Batch batch)
	{
		poster.post(batch.urls, join(batch.notifications), batch.image);
	}

	static String join(List<Notification> notifications)
	{
		return mergePet(mergeLoot(notifications)).stream()
			.sorted(Comparator.comparing(Notification::getType))
			.map(Notification::getText)
			.collect(Collectors.joining("\n"));
	}

	// Runs before mergePet so a pet with no name can't take the name of a real drop
	private static List<Notification> mergeLoot(List<Notification> notifications)
	{
		List<Notification> merged = new ArrayList<>(notifications);
		for (Notification loot : notifications)
		{
			if (loot.getType() == NotificationType.LOOT
				&& merged.removeIf(n -> n.getType() == NotificationType.COLLECTION_LOG && listsItem(loot, n.getPlaceholders().get("entry"))))
			{
				merged.set(merged.indexOf(loot), loot.toBuilder().text(loot.getText() + NEW_ENTRY_NOTE).build());
			}
		}
		return merged;
	}

	private static boolean listsItem(Notification loot, String item)
	{
		return loot.getItemNames().stream().anyMatch(name -> name.equalsIgnoreCase(item));
	}

	private static List<Notification> mergePet(List<Notification> notifications)
	{
		Notification pet = notifications.stream()
			.filter(n -> n.getType() == NotificationType.PET)
			.findFirst()
			.orElse(null);
		if (pet == null)
		{
			return notifications;
		}

		String name = pet.getPlaceholders().get("pet");
		if (name != null)
		{
			return notifications.stream()
				.filter(n -> n.getType() != NotificationType.COLLECTION_LOG
					|| !name.equalsIgnoreCase(n.getPlaceholders().get("entry")))
				.collect(Collectors.toList());
		}

		List<Notification> logs = notifications.stream()
			.filter(n -> n.getType() == NotificationType.COLLECTION_LOG)
			.collect(Collectors.toList());
		if (pet.getNamedText() == null || logs.size() != 1)
		{
			return notifications;
		}

		Map<String, String> values = new HashMap<>(pet.getPlaceholders());
		values.put("pet", logs.get(0).getPlaceholders().get("entry"));

		List<Notification> merged = new ArrayList<>(notifications);
		merged.remove(logs.get(0));
		merged.set(merged.indexOf(pet), pet.toBuilder().text(Template.render(pet.getNamedText(), values)).build());
		return merged;
	}

	private static class Batch
	{
		final List<String> urls;
		long deadline;
		final List<Notification> notifications = new ArrayList<>();
		boolean captureRequested;
		boolean captureDone;
		byte[] image;

		Batch(List<String> urls, long deadline)
		{
			this.urls = urls;
			this.deadline = deadline;
		}
	}
}

package com.discordnotifications;

import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.Collection;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

@Singleton
public class NpcLootPairing
{
	enum Signal
	{
		TILE_SCAN,
		SERVER
	}

	// Core can hold the tile scan for 10 ticks (6 s) after the kill
	private static final Duration WINDOW = Duration.ofSeconds(8);

	@Inject
	private ItemManager itemManager;

	private final Deque<Kill> unpaired = new ArrayDeque<>();

	void reset()
	{
		unpaired.clear();
	}

	boolean isNewKill(String source, Collection<ItemStack> items, Signal signal, Instant now)
	{
		while (!unpaired.isEmpty() && Duration.between(unpaired.peek().time, now).compareTo(WINDOW) > 0)
		{
			unpaired.poll();
		}

		Map<Integer, Integer> totals = totals(items);
		Kill pair = findPair(source, totals, signal);
		if (pair != null)
		{
			unpaired.remove(pair);
			return false;
		}

		unpaired.add(new Kill(source, totals, signal, now));
		return true;
	}

	// Tightest match first, so a loose one can't take the pair of the kill queued behind it
	private Kill findPair(String source, Map<Integer, Integer> totals, Signal signal)
	{
		Kill subset = null;
		Kill oneSided = null;
		for (Kill kill : unpaired)
		{
			if (kill.signal == signal || !kill.source.equals(source))
			{
				continue;
			}

			if (kill.totals.equals(totals))
			{
				return kill;
			}
			if (subset == null && (containedIn(kill.totals, totals) || containedIn(totals, kill.totals)))
			{
				subset = kill;
			}
			if (oneSided == null && differsOnlyInOneSidedItems(kill.totals, totals))
			{
				oneSided = kill;
			}
		}
		return subset != null ? subset : oneSided;
	}

	private boolean differsOnlyInOneSidedItems(Map<Integer, Integer> a, Map<Integer, Integer> b)
	{
		Set<Integer> ids = new HashSet<>(a.keySet());
		ids.addAll(b.keySet());

		boolean shared = false;
		for (int id : ids)
		{
			if (a.getOrDefault(id, 0).equals(b.getOrDefault(id, 0)))
			{
				shared = true;
			}
			else if (!isOneSidedItem(id))
			{
				return false;
			}
		}
		return shared;
	}

	// Bonecrusher and ash sanctifier keep these off the ground, clue drops can be missing from either list
	private boolean isOneSidedItem(int id)
	{
		ItemComposition item = itemManager.getItemComposition(id);
		String name = item == null || item.getName() == null ? "" : item.getName().toLowerCase(Locale.ROOT);
		return name.endsWith("bones") || name.endsWith("ashes") || name.startsWith("scroll box (") || name.startsWith("clue scroll (");
	}

	private static boolean containedIn(Map<Integer, Integer> part, Map<Integer, Integer> whole)
	{
		return part.entrySet().stream().allMatch(item -> whole.getOrDefault(item.getKey(), 0) >= item.getValue());
	}

	// Summed because the events stack non-stackables differently
	private static Map<Integer, Integer> totals(Collection<ItemStack> items)
	{
		Map<Integer, Integer> totals = new HashMap<>();
		for (ItemStack item : items)
		{
			totals.merge(item.getId(), item.getQuantity(), Integer::sum);
		}
		return totals;
	}

	private static class Kill
	{
		private final String source;
		private final Map<Integer, Integer> totals;
		private final Signal signal;
		private final Instant time;

		Kill(String source, Map<Integer, Integer> totals, Signal signal, Instant time)
		{
			this.source = source;
			this.totals = totals;
			this.signal = signal;
			this.time = time;
		}
	}
}

package com.discordnotifications;

import lombok.extern.slf4j.Slf4j;

import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.ImageOutputStream;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

@Slf4j
final class ScreenshotEncoder
{
	static final int MAX_IMAGE_BYTES = 8_000_000;
	private static final float JPEG_QUALITY = 0.85f;

	private ScreenshotEncoder()
	{
	}

	static byte[] encode(Image image)
	{
		if (!(image instanceof BufferedImage))
		{
			return null;
		}

		try
		{
			return encodeUnderLimit((BufferedImage) image);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Error converting image to byte array", e);
			return null;
		}
	}

	static byte[] encodeUnderLimit(BufferedImage image) throws IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		ImageIO.write(image, "png", out);
		byte[] png = out.toByteArray();
		if (png.length <= MAX_IMAGE_BYTES)
		{
			return png;
		}

		byte[] jpeg = encodeJpeg(scaleToRgb(image, Math.sqrt((double) MAX_IMAGE_BYTES / png.length)));
		if (jpeg.length > MAX_IMAGE_BYTES)
		{
			// Discord would reject the whole post, the text is still worth sending
			log.warn("Screenshot still {} bytes after scaling, sending without it", jpeg.length);
			return null;
		}
		return jpeg;
	}

	private static BufferedImage scaleToRgb(BufferedImage image, double factor)
	{
		int width = Math.max(1, (int) (image.getWidth() * factor));
		int height = Math.max(1, (int) (image.getHeight() * factor));

		// The JPEG writer writes nothing at all for an image with alpha
		BufferedImage scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = scaled.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		graphics.drawImage(image, 0, 0, width, height, null);
		graphics.dispose();
		return scaled;
	}

	private static byte[] encodeJpeg(BufferedImage image) throws IOException
	{
		ImageWriter writer = ImageIO.getImageWritersByFormatName("jpeg").next();
		try (ByteArrayOutputStream out = new ByteArrayOutputStream();
			ImageOutputStream stream = ImageIO.createImageOutputStream(out))
		{
			ImageWriteParam param = writer.getDefaultWriteParam();
			param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
			param.setCompressionQuality(JPEG_QUALITY);
			writer.setOutput(stream);
			writer.write(null, new IIOImage(image, null, null), param);
			stream.flush();
			return out.toByteArray();
		}
		finally
		{
			writer.dispose();
		}
	}

	// The queue only carries bytes. PNG starts with 0x89, JPEG with FF D8
	static boolean isJpeg(byte[] image)
	{
		return image != null && image.length >= 2 && image[0] == (byte) 0xFF && image[1] == (byte) 0xD8;
	}
}

