package com.discordnotifications;

import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public final class Template
{
	private static final Pattern PLACEHOLDER = Pattern.compile("\\$([a-zA-Z]+)");
	private static final Pattern MARKDOWN = Pattern.compile("[\\\\*_~`|>]");

	private Template()
	{
	}

	public static String render(String template, Map<String, String> values)
	{
		return PLACEHOLDER.matcher(template).replaceAll(match ->
			Matcher.quoteReplacement(escapeMarkdown(values.getOrDefault(match.group(1), ""))));
	}

	private static String escapeMarkdown(String value)
	{
		return MARKDOWN.matcher(value).replaceAll("\\\\$0");
	}
}

package com.discordnotifications;

import java.util.Arrays;
import java.util.List;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public final class WildcardList
{
	private final List<Pattern> patterns;

	private WildcardList(List<Pattern> patterns)
	{
		this.patterns = patterns;
	}

	public static WildcardList parse(String text)
	{
		return new WildcardList(entries(text, "[\n,;]")
			.map(WildcardList::toPattern)
			.collect(Collectors.toList()));
	}

	static Stream<String> entries(String text, String separators)
	{
		return Arrays.stream(text.split(separators))
			.map(String::trim)
			.filter(entry -> !entry.isEmpty());
	}

	public boolean matches(String value)
	{
		return patterns.stream().anyMatch(pattern -> pattern.matcher(value).matches());
	}

	private static Pattern toPattern(String wildcard)
	{
		String regex = Arrays.stream(wildcard.split("\\*", -1))
			.map(Pattern::quote)
			.collect(Collectors.joining(".*"));
		return Pattern.compile(regex, Pattern.CASE_INSENSITIVE);
	}
}

package com.discordnotifications;

import com.google.common.collect.ImmutableSet;
import com.google.common.collect.Sets;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.WorldType;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;

public final class WorldUtils
{
	private static final Set<WorldType> IGNORED = EnumSet.of(
		WorldType.PVP_ARENA,
		WorldType.QUEST_SPEEDRUNNING,
		WorldType.BETA_WORLD,
		WorldType.NOSAVE_MODE,
		WorldType.TOURNAMENT_WORLD);

	// Seasonal Deadman and Grid Master worlds carry the tournament flag too
	private static final Set<WorldType> IGNORED_ON_SEASONAL = Sets.difference(IGNORED, EnumSet.of(WorldType.TOURNAMENT_WORLD));

	private static final Set<WorldType> SEPARATE_STATS = Sets.union(IGNORED, EnumSet.of(WorldType.DEADMAN, WorldType.SEASONAL));

	private static final Set<Integer> BA_REGIONS = ImmutableSet.of(7508, 7509, 10322);
	private static final Set<Integer> CASTLE_WARS_REGIONS = ImmutableSet.of(9520, 9620);
	private static final Set<Integer> CLAN_WARS_REGIONS = ImmutableSet.of(12621, 12622, 12623, 13130, 13131, 13133, 13134, 13135, 13386, 13387, 13390, 13641, 13642, 13643, 13644, 13645, 13646, 13647, 13899, 13900, 14155, 14156);
	private static final Set<Integer> COX_REGIONS = ImmutableSet.of(12889, 13136, 13137, 13138, 13139, 13140, 13141, 13145, 13393, 13394, 13395, 13396, 13397, 13401);
	private static final Set<Integer> GALVEK_REGIONS = ImmutableSet.of(6486, 6487, 6488, 6489, 6742, 6743, 6744, 6745);
	private static final Set<Integer> GAUNTLET_REGIONS = ImmutableSet.of(7512, 7768, 12127);
	private static final Set<Integer> LMS_REGIONS = ImmutableSet.of(13658, 13659, 13660, 13914, 13915, 13916, 13918, 13919, 13920, 14174, 14175, 14176, 14430, 14431, 14432);
	private static final Set<Integer> POH_REGIONS = ImmutableSet.of(7257, 7534, 7535, 7790, 7791, 8046, 8047, 8302, 8303);
	private static final Set<Integer> SOUL_WARS_REGIONS = ImmutableSet.of(8493, 8748, 8749, 9005);
	private static final Set<Integer> TOA_REGIONS = ImmutableSet.of(14160, 14162, 14164, 14674, 14676, 15184, 15186, 15188, 15696, 15698, 15700);
	private static final Set<Integer> TOB_REGIONS = ImmutableSet.of(12611, 12612, 12613, 12867, 12869, 13122, 13123, 13125, 13379);
	private static final Set<Integer> ZULRAH_REGIONS = ImmutableSet.of(9007, 9008);
	private static final int INFERNO_REGION = 9043;
	private static final int MAGE_TRAINING_GRAVEYARD_REGION = 13462;
	private static final int NMZ_REGION = 9033;
	private static final int FIGHT_CAVE_REGION = 9551;
	private static final int FIGHT_PIT_REGION = 9552;
	private static final int CLAN_HALL_REGION = 6997;
	public static final int FORTIS_REGION = 7216;

	private static final int DS2_COMPLETED = 215;
	private static final int ACCOUNT_HARDCORE = 3;
	private static final int ACCOUNT_HARDCORE_GROUP = 5;

	private WorldUtils()
	{
	}

	public static boolean isGridMaster(Client client)
	{
		return client.getWorldType().contains(WorldType.TOURNAMENT_WORLD)
			&& client.getVarbitValue(VarbitID.BINGO_INITIAL_SETUP_DONE) > 0;
	}

	public static boolean isIgnoredWorld(Set<WorldType> worldTypes, boolean gridMaster)
	{
		boolean seasonal = gridMaster || worldTypes.contains(WorldType.DEADMAN);
		return !Collections.disjoint(seasonal ? IGNORED_ON_SEASONAL : IGNORED, worldTypes);
	}

	public static String gameModePrefix(Set<WorldType> worldTypes, boolean gridMaster)
	{
		if (worldTypes.contains(WorldType.DEADMAN))
		{
			return "[DMM] ";
		}

		if (gridMaster)
		{
			return "[Grid Master] ";
		}

		return worldTypes.contains(WorldType.SEASONAL) ? "[Leagues] " : "";
	}

	public static Set<WorldType> separateStatsTypes(Set<WorldType> worldTypes)
	{
		return Sets.intersection(worldTypes, SEPARATE_STATS).immutableCopy();
	}

	// Instances report made up coordinates from getWorldLocation
	public static WorldPoint getLocation(Client client, Actor actor)
	{
		WorldView view = actor.getWorldView();
		return view.isInstance()
			? WorldPoint.fromLocalInstance(client, actor.getLocalLocation(), view.getPlane())
			: actor.getWorldLocation();
	}

	public static boolean isHardcore(Client client)
	{
		int account = client.getVarbitValue(VarbitID.IRONMAN);
		return account == ACCOUNT_HARDCORE || account == ACCOUNT_HARDCORE_GROUP;
	}

	public static boolean canBePked(Client client)
	{
		Set<WorldType> worldTypes = client.getWorldType();
		boolean pvpArea = client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) > 0
			|| worldTypes.contains(WorldType.PVP)
			|| worldTypes.contains(WorldType.DEADMAN);
		return pvpArea && !isVisible(client, InterfaceID.PvpIcons.PVPW_SAFE);
	}

	public static DangerLevel getDangerLevel(Client client, int regionId)
	{
		boolean hardcoreGroup = client.getVarbitValue(VarbitID.IRONMAN) == ACCOUNT_HARDCORE_GROUP;

		// Plain hardcores lose their status in these three but not in the other PvM activities
		if (GAUNTLET_REGIONS.contains(regionId) || TOA_REGIONS.contains(regionId) || TOB_REGIONS.contains(regionId))
		{
			return isHardcore(client) ? DangerLevel.DANGEROUS : DangerLevel.SAFE;
		}

		if (regionId == FIGHT_CAVE_REGION)
		{
			return hardcoreGroup ? DangerLevel.DANGEROUS : DangerLevel.EXCEPTIONAL;
		}

		if (regionId == INFERNO_REGION)
		{
			if (hardcoreGroup)
			{
				return DangerLevel.DANGEROUS;
			}

			// Jad challenges share the Inferno's region
			return client.getVarpValue(VarPlayerID.SA_ENERGY_STORED) == 0 ? DangerLevel.EXCEPTIONAL : DangerLevel.SAFE;
		}

		// Western Provinces elite gives one free resurrection a day
		if (ZULRAH_REGIONS.contains(regionId) && client.getVarbitValue(VarbitID.ZULRAH_REVIVE) == 0
			&& client.getVarbitValue(VarbitID.WESTERN_DIARY_ELITE_COMPLETE) > 0)
		{
			return DangerLevel.SAFE;
		}

		if (COX_REGIONS.contains(regionId) || BA_REGIONS.contains(regionId) || regionId == NMZ_REGION
			|| regionId == MAGE_TRAINING_GRAVEYARD_REGION
			|| isVisible(client, InterfaceID.PestStatusOverlay.PEST_STATUS_PORT2)
			|| (GALVEK_REGIONS.contains(regionId) && client.getVarbitValue(VarbitID.DS2) >= DS2_COMPLETED))
		{
			return hardcoreGroup ? DangerLevel.DANGEROUS : DangerLevel.SAFE;
		}

		if (CASTLE_WARS_REGIONS.contains(regionId) || CLAN_WARS_REGIONS.contains(regionId)
			|| SOUL_WARS_REGIONS.contains(regionId) || POH_REGIONS.contains(regionId)
			|| regionId == CLAN_HALL_REGION || regionId == FIGHT_PIT_REGION
			|| LMS_REGIONS.contains(regionId) || isVisible(client, InterfaceID.BrOverlay.CONTENT))
		{
			return DangerLevel.SAFE;
		}

		return DangerLevel.DANGEROUS;
	}

	static boolean isVisible(Client client, int componentId)
	{
		Widget widget = client.getWidget(componentId);
		return widget != null && !widget.isHidden();
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.DiscordNotificationsConfig;
import com.discordnotifications.DiscordWebhookService;
import com.discordnotifications.Notification;
import com.discordnotifications.NotificationType;
import com.discordnotifications.SeasonalWorlds;
import com.discordnotifications.Template;
import com.discordnotifications.WorldUtils;
import com.google.common.base.Strings;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldType;

import javax.inject.Inject;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * The webhook service is private on purpose: subclasses build message text and call {@link #send},
 * and nothing else in the plugin can reach the network.
 */
@Slf4j
public abstract class BaseNotifier
{
	private static final Pattern TAG_REGEXP = Pattern.compile("(<[^>]*>)|(@[^@\\s]+@)");

	@Inject
	protected Client client;

	@Inject
	protected DiscordNotificationsConfig config;

	@Inject
	private DiscordWebhookService webhookService;

	@Inject
	private HeldNotifications heldNotifications;

	public void reset()
	{
	}

	protected final void send(NotificationType type, String template, Map<String, String> placeholders, boolean screenshot)
	{
		send(Notification.builder()
			.type(type)
			.text(template)
			.placeholders(placeholders)
			.screenshot(screenshot)
			.build());
	}

	// The local player exists but has no name for the first ticks after login.
	protected final void send(Notification notification)
	{
		if (!deliver(notification))
		{
			heldNotifications.add(() -> deliver(notification));
		}
	}

	private boolean deliver(Notification notification)
	{
		String localName = playerName();
		if (Strings.isNullOrEmpty(localName))
		{
			return false;
		}

		Set<WorldType> worldTypes = client.getWorldType();
		boolean gridMaster = WorldUtils.isGridMaster(client);
		String prefix = WorldUtils.gameModePrefix(worldTypes, gridMaster);
		if (WorldUtils.isIgnoredWorld(worldTypes, gridMaster) || (!prefix.isEmpty() && config.seasonalWorlds() == SeasonalWorlds.IGNORE))
		{
			log.debug("Dropping notification, ignored world {}", worldTypes);
			return true;
		}

		Map<String, String> values = new HashMap<>(notification.getPlaceholders());
		values.put("name", localName);

		webhookService.send(notification.toBuilder()
			.text(prefix + Template.render(notification.getText(), values))
			// The queue renders this later, when it works out the pet's name
			.namedText(notification.getNamedText() == null ? null : prefix + notification.getNamedText())
			.placeholders(values)
			.build());
		return true;
	}

	protected String playerName()
	{
		Player player = client.getLocalPlayer();
		return player != null ? player.getName() : null;
	}

	public static String sanitize(String text)
	{
		if (text == null)
		{
			return "";
		}

		return TAG_REGEXP.matcher(text.replace("<br>", " "))
			.replaceAll("")
			.replace(' ', ' ')
			.trim();
	}

	// Popup body is "New item: <col=..>Item</col>" or "Task Completed: <col=..>Task</col>".
	static String popupSubject(String bottomText)
	{
		String text = sanitize(bottomText);
		int colon = text.indexOf(':');
		return colon < 0 ? text : text.substring(colon + 1).trim();
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.CompletedClue;
import com.discordnotifications.ItemStackFormatter;
import com.discordnotifications.NotificationType;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.QuantityFormatter;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

@Singleton
public class ClueNotifier extends BaseNotifier
{
	@Inject
	private ItemStackFormatter itemStackFormatter;

	private CompletedClue pending;
	private int badTicks;

	@Override
	public void reset()
	{
		pending = null;
		badTicks = 0;
	}

	public void onGameMessage(String chatMessage)
	{
		if (!config.includeClues())
		{
			return;
		}

		CompletedClue completed = CompletedClue.parse(chatMessage);
		if (completed != null && completed.getTier().ordinal() >= config.minClueTier().ordinal())
		{
			pending = completed;
			badTicks = 0;
		}
	}

	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() != InterfaceID.TRAIL_REWARDSCREEN || pending == null)
		{
			return;
		}

		sendClue(pending, rewards());
		reset();
	}

	// The chat message comes first, so a screen that never loaded can't pair with the next clue
	public void onGameTick()
	{
		if (pending != null && ++badTicks > 1)
		{
			reset();
		}
	}

	private List<ItemStackFormatter.Stack> rewards()
	{
		Map<Integer, Integer> quantities = new LinkedHashMap<>();
		ItemContainer container = client.getItemContainer(InventoryID.TRAIL_REWARDINV);
		if (container != null)
		{
			for (Item item : container.getItems())
			{
				addReward(quantities, item.getId(), item.getQuantity());
			}
		}

		Widget items = client.getWidget(InterfaceID.TrailRewardscreen.ITEMS);
		Widget[] children = items == null ? null : items.getChildren();
		if (quantities.isEmpty() && children != null)
		{
			for (Widget child : children)
			{
				if (child != null)
				{
					addReward(quantities, child.getItemId(), child.getItemQuantity());
				}
			}
		}

		return quantities.entrySet().stream()
			.map(entry -> itemStackFormatter.stackWithStorePrice(entry.getKey(), entry.getValue()))
			.collect(Collectors.toList());
	}

	private static void addReward(Map<Integer, Integer> quantities, int itemId, int quantity)
	{
		if (itemId > -1 && quantity > 0)
		{
			quantities.merge(itemId, quantity, Integer::sum);
		}
	}

	private void sendClue(CompletedClue completed, List<ItemStackFormatter.Stack> rewards)
	{
		long value = ItemStackFormatter.totalValue(rewards);
		// No rewards means we couldn't read them, so there's no value to filter on
		if (!rewards.isEmpty() && value < config.minClueValue())
		{
			return;
		}

		send(NotificationType.CLUE, config.clueMessage(), placeholders(completed, rewards), config.sendClueScreenshot());
	}

	static Map<String, String> placeholders(CompletedClue completed, List<ItemStackFormatter.Stack> rewards)
	{
		Map<String, String> placeholders = new HashMap<>();
		placeholders.put("tier", completed.getTier().toString());
		placeholders.put("count", QuantityFormatter.formatNumber(completed.getCount()));
		placeholders.put("items", ItemStackFormatter.format(rewards));
		placeholders.put("value", QuantityFormatter.quantityToStackSize(ItemStackFormatter.totalValue(rewards)));
		return placeholders;
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.CollectionLogRank;
import com.discordnotifications.KillCountService;
import com.discordnotifications.Notification;
import com.discordnotifications.NotificationType;
import com.discordnotifications.WildcardList;
import com.discordnotifications.WorldUtils;
import net.runelite.api.ScriptID;
import net.runelite.api.WorldType;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.QuantityFormatter;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.ToIntFunction;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

@Singleton
public class CollectionLogNotifier extends BaseNotifier
{
	static final Pattern COLLECTION_LOG_REGEX = Pattern.compile("New item added to your collection log: (?<item>.*)");

	// Any other value that gives a message also shows the popup
	private static final int NEW_ITEM_CHAT_ONLY = 1;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private KillCountService killCountService;

	private final Set<String> entriesThisTick = new HashSet<>();
	private int entriesTick = -1;
	private int completed = 0;
	private Set<WorldType> countedWorldTypes = null;
	private boolean popupStarted = false;

	@Override
	public void reset()
	{
		entriesThisTick.clear();
		entriesTick = -1;
		completed = 0;
		countedWorldTypes = null;
		popupStarted = false;
	}

	public void onGameTick()
	{
		resetIfWorldChanged();

		// The varp lags our local count, max stops it pulling the count back
		completed = Math.max(completed, client.getVarpValue(VarPlayerID.COLLECTION_COUNT));
	}

	// Worlds with their own stats have their own log, max would keep the larger count
	private void resetIfWorldChanged()
	{
		Set<WorldType> worldTypes = WorldUtils.separateStatsTypes(client.getWorldType());
		if (!worldTypes.equals(countedWorldTypes))
		{
			completed = 0;
			countedWorldTypes = worldTypes;
		}
	}

	public void onGameMessage(String chatMessage)
	{
		if (!config.includeCollectionLogs() || client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) != NEW_ITEM_CHAT_ONLY)
		{
			return;
		}

		String entry = parseEntry(chatMessage);
		if (entry != null)
		{
			queueEntry(entry);
		}
	}

	public void onScriptPreFired(ScriptPreFired scriptPreFired)
	{
		switch (scriptPreFired.getScriptId())
		{
			case ScriptID.NOTIFICATION_START:
				popupStarted = true;
				break;
			case ScriptID.NOTIFICATION_DELAY:
				if (!popupStarted)
				{
					return;
				}
				popupStarted = false;

				String topText = sanitize(client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE));
				if (topText.equalsIgnoreCase("Collection log") && config.includeCollectionLogs())
				{
					queueEntry(popupSubject(client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN)));
				}
				break;
		}
	}

	private void queueEntry(String entry)
	{
		int tick = client.getTickCount();
		if (tick != entriesTick)
		{
			entriesTick = tick;
			entriesThisTick.clear();
		}

		if (entriesThisTick.add(entry))
		{
			clientThread.invokeAtTickEnd(() -> sendEntry(entry));
		}
	}

	private void sendEntry(String entry)
	{
		// Before the denylist check, a skipped item still fills a slot
		if (completed > 0)
		{
			completed++;
		}

		if (WildcardList.parse(config.collectionLogDenylist()).matches(entry))
		{
			return;
		}

		Map<String, String> placeholders = new HashMap<>();
		placeholders.put("entry", entry);

		CollectionLogRank rankUp = null;
		int total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
		if (completed > 0 && total > 0)
		{
			String completedText = QuantityFormatter.formatNumber(completed);
			String totalText = QuantityFormatter.formatNumber(total);
			placeholders.put("completed", completedText);
			placeholders.put("total", totalText);
			placeholders.put("progress", " (" + completedText + "/" + totalText + ")");

			ToIntFunction<CollectionLogRank> thresholds = r -> r.threshold(client, total);
			CollectionLogRank rank = CollectionLogRank.at(completed, thresholds);
			if (rank != null)
			{
				placeholders.put("rank", rank.toString());
			}
			if (rank != CollectionLogRank.at(completed - 1, thresholds))
			{
				rankUp = rank;
			}
		}

		KillCountService.Drop drop = killCountService.getRecentDrop();
		if (drop != null && cameFrom(entry, itemNames(drop)))
		{
			placeholders.putAll(KillCountService.sourcePlaceholders(sanitize(drop.getSource()), killCountService.getKillCount(drop.getType(), drop.getSource())));
		}

		send(NotificationType.COLLECTION_LOG, config.collectionLogMessage(), placeholders, config.sendCollectionLogScreenshot());

		// Its own notification because the queue drops the clog line when it merges into a loot or pet line
		if (rankUp != null)
		{
			send(Notification.builder()
				.type(NotificationType.COLLECTION_LOG_RANK)
				.text("$name has just reached " + rankUp + " rank in the collection log")
				.build());
		}
	}

	private List<String> itemNames(KillCountService.Drop drop)
	{
		return drop.getItems().stream()
			.map(item -> itemManager.getItemComposition(item.getId()).getMembersName())
			.collect(Collectors.toList());
	}

	// A drop set from chat has no items yet, pets are never part of a drop
	static boolean cameFrom(String entry, List<String> dropItems)
	{
		return dropItems.isEmpty() || PetNotifier.isPet(entry) || dropItems.stream().anyMatch(entry::equalsIgnoreCase);
	}

	static String parseEntry(String message)
	{
		Matcher matcher = COLLECTION_LOG_REGEX.matcher(message);
		return matcher.matches() ? matcher.group("item") : null;
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.CombatAchievementTier;
import com.discordnotifications.NotificationType;
import lombok.Value;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.QuantityFormatter;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;
import java.util.function.ToIntFunction;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Singleton
public class CombatAchievementNotifier extends BaseNotifier
{
	private static final Pattern TASK_REGEX = Pattern.compile("Congratulations, you've completed an? (?<tier>\\w+) combat task: (?<task>.+)\\.");
	private static final Pattern POINTS_SUFFIX = Pattern.compile("\\s+\\(\\d+ points?\\)$");

	@Inject
	private ClientThread clientThread;

	public void onGameMessage(String chatMessage)
	{
		if (!config.includeCombatAchievements())
		{
			return;
		}

		CompletedTask completed = parse(chatMessage);
		if (completed != null && completed.getTier().ordinal() >= config.minCombatAchievementTier().ordinal())
		{
			// CA_POINTS hasn't updated yet when the message arrives
			clientThread.invokeAtTickEnd(() -> sendTask(completed));
		}
	}

	private void sendTask(CompletedTask completed)
	{
		int totalPoints = client.getVarbitValue(VarbitID.CA_POINTS);
		CombatAchievementTier unlocked = unlockedTier(totalPoints, completed.getTier().getPoints(),
			tier -> client.getVarbitValue(tier.getThresholdVarbit()));

		send(NotificationType.COMBAT_ACHIEVEMENT, config.combatAchievementsMessage(),
			placeholders(completed, totalPoints, unlocked),
			config.sendCombatAchievementsScreenshot());
	}

	static CompletedTask parse(String message)
	{
		Matcher matcher = TASK_REGEX.matcher(message);
		if (!matcher.find())
		{
			return null;
		}

		CombatAchievementTier tier = CombatAchievementTier.fromName(matcher.group("tier"));
		if (tier == null)
		{
			return null;
		}

		return new CompletedTask(tier, POINTS_SUFFIX.matcher(matcher.group("task")).replaceFirst(""));
	}

	static CombatAchievementTier unlockedTier(int totalPoints, int taskPoints, ToIntFunction<CombatAchievementTier> thresholds)
	{
		for (CombatAchievementTier tier : CombatAchievementTier.values())
		{
			int threshold = thresholds.applyAsInt(tier);
			if (threshold > 0 && totalPoints >= threshold && totalPoints - taskPoints < threshold)
			{
				return tier;
			}
		}
		return null;
	}

	static Map<String, String> placeholders(CompletedTask completed, int totalPoints, CombatAchievementTier unlocked)
	{
		Map<String, String> placeholders = new HashMap<>();
		placeholders.put("task", completed.getTask());
		placeholders.put("achievement", completed.getTask());
		placeholders.put("tier", completed.getTier().toString());
		placeholders.put("points", String.valueOf(completed.getTier().getPoints()));
		if (totalPoints > 0)
		{
			placeholders.put("totalPoints", QuantityFormatter.formatNumber(totalPoints));
		}
		if (unlocked != null)
		{
			placeholders.put("tierUnlocked", " and unlocked the " + unlocked + " tier");
		}
		return placeholders;
	}

	@Value
	static class CompletedTask
	{
		CombatAchievementTier tier;
		String task;
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.DangerLevel;
import com.discordnotifications.NotificationType;
import com.discordnotifications.WildcardList;
import com.discordnotifications.WorldUtils;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.ScriptPreFired;

import javax.inject.Singleton;
import java.lang.ref.WeakReference;
import java.util.Collections;
import java.util.Comparator;
import java.util.stream.Stream;

@Singleton
public class DeathNotifier extends BaseNotifier
{
	private static final String TOA_WIPE_MESSAGE = "You failed to survive the Tombs of Amascut";
	private static final String TOB_WIPE_MESSAGE = "Your party has failed";
	private static final String DOOM_MESSAGE = "You have been doomed!";
	private static final int TOB_HUD_PORTAL_SCRIPT = 2307;
	private static final int KILLER_WINDOW_TICKS = 17;

	private WeakReference<Actor> lastTarget = new WeakReference<>(null);
	private int lastTargetTick;
	private boolean targetingLast;

	@Override
	public void reset()
	{
		lastTarget.clear();
		lastTargetTick = 0;
		targetingLast = false;
	}

	public void onActorDeath(ActorDeath actorDeath)
	{
		Actor actor = actorDeath.getActor();
		boolean self = actor == client.getLocalPlayer();
		if (self && config.includeDeaths())
		{
			notifyDeath(false);
		}

		if (self || actor == lastTarget.get())
		{
			lastTarget.clear();
		}
	}

	public void onGameMessage(String message)
	{
		if (message.equals(DOOM_MESSAGE))
		{
			// Doom kills you without reaching 0 HP, so there's no ActorDeath
			Player player = client.getLocalPlayer();
			if (config.includeDeaths() && player != null && client.getBoostedSkillLevel(Skill.HITPOINTS) > 0
				&& WorldUtils.getLocation(client, player).getRegionID() == WorldUtils.FORTIS_REGION)
			{
				notifyDeath(true);
			}
		}
		else if (message.contains(TOA_WIPE_MESSAGE) && wipeNotAlreadySent())
		{
			notifyDeath(true);
		}
	}

	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != TOB_HUD_PORTAL_SCRIPT || event.getScriptEvent() == null)
		{
			return;
		}

		Object[] args = event.getScriptEvent().getArguments();
		if (args != null && args.length > 1 && args[1] instanceof String
			&& ((String) args[1]).contains(TOB_WIPE_MESSAGE) && wipeNotAlreadySent())
		{
			notifyDeath(true);
		}
	}

	public void onInteractingChanged(InteractingChanged event)
	{
		if (event.getSource() != client.getLocalPlayer())
		{
			return;
		}

		Actor target = event.getTarget();
		boolean accepted = target != null && target.getCombatLevel() > 0;
		if (accepted)
		{
			lastTarget = new WeakReference<>(target);
		}

		// Running from a fight still counts as recent, so the window starts when you disengage
		if (accepted || (target == null && targetingLast))
		{
			lastTargetTick = client.getTickCount();
		}
		targetingLast = accepted;
	}

	// With safe deaths on, or on a hardcore, the ActorDeath in the raid was already posted
	private boolean wipeNotAlreadySent()
	{
		return config.includeDeaths() && config.ignoreSafeDeaths() && !WorldUtils.isHardcore(client);
	}

	private void notifyDeath(boolean alwaysDangerous)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}

		int regionId = WorldUtils.getLocation(client, player).getRegionID();
		if (WildcardList.parse(config.deathIgnoredRegions()).matches(String.valueOf(regionId)))
		{
			return;
		}

		if (!alwaysDangerous && config.ignoreSafeDeaths() && WorldUtils.getDangerLevel(client, regionId) == DangerLevel.SAFE)
		{
			return;
		}

		Actor killer = findKiller(player);
		String killerName = killer == null ? "" : sanitize(killer.getName());

		String template = config.deathMessage();
		if (!killerName.isEmpty())
		{
			template = killer instanceof Player ? config.deathPvpMessage() : config.deathNpcMessage();
		}

		send(NotificationType.DEATH, template, Collections.singletonMap("killer", killerName), config.sendDeathScreenshot());
	}

	private Actor findKiller(Player player)
	{
		Actor target = lastTarget.get();
		if (isLastTargetKiller(player, target))
		{
			return target;
		}

		if (WorldUtils.canBePked(client))
		{
			Actor pker = closestAttacker(player, client.getTopLevelWorldView().players().stream().filter(DeathNotifier::isHostile));
			if (pker != null)
			{
				return pker;
			}
		}

		return closestAttacker(player, client.getTopLevelWorldView().npcs().stream().filter(DeathNotifier::isCombatNpc));
	}

	private boolean isLastTargetKiller(Player player, Actor target)
	{
		if (target == null || target.isDead() || target.getInteracting() != player)
		{
			return false;
		}

		// InteractingChanged doesn't fire during a long fight, so still targeting it counts as recent
		if (player.getInteracting() != target && client.getTickCount() - lastTargetTick > KILLER_WINDOW_TICKS)
		{
			return false;
		}

		return !(target instanceof Player) || (WorldUtils.canBePked(client) && isHostile((Player) target));
	}

	private static Actor closestAttacker(Player player, Stream<? extends Actor> candidates)
	{
		Comparator<Actor> nearest = Comparator.comparingInt(a -> a.getLocalLocation().distanceTo(player.getLocalLocation()));
		return candidates
			.filter(a -> a.getInteracting() == player && !a.isDead())
			.min(nearest.thenComparing(Actor::getCombatLevel, Comparator.reverseOrder()))
			.orElse(null);
	}

	// Friends following you also show up as interacting
	private static boolean isHostile(Player other)
	{
		return !other.isFriend() && !other.isClanMember() && !other.isFriendsChatMember();
	}

	private static boolean isCombatNpc(NPC npc)
	{
		NPCComposition composition = npc.getTransformedComposition();
		return composition != null && composition.isInteractible() && !composition.isFollower() && composition.getCombatLevel() > 0;
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.AchievementDiary;
import com.discordnotifications.DiaryDifficulty;
import com.discordnotifications.NotificationType;
import com.google.common.collect.ImmutableMap;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Singleton
public class DiaryNotifier extends BaseNotifier
{
	private static final Pattern COMPLETION_REGEX = Pattern.compile("Congratulations! You have completed all of the (?<difficulty>.+) tasks in the (?<area>.+?) area");
	private static final int SNAPSHOT_DELAY_TICKS = 4;
	private static final int COOLDOWN_TICKS = 2;
	// CS2 procs, RuneLite has no ScriptID constants for these
	private static final int COMPLETED_TASKS_SCRIPT = 3971;
	private static final int TOTAL_TASKS_SCRIPT = 3980;
	private static final int COMPLETED_AREA_TASKS_SCRIPT = 4072;
	private static final int TOTAL_AREA_TASKS_SCRIPT = 4073;
	static final Map<String, Integer> SCRIPT_AREA_IDS = ImmutableMap.<String, Integer>builder()
		.put("Karamja", 0)
		.put("Ardougne", 1)
		.put("Falador", 2)
		.put("Fremennik", 3)
		.put("Kandarin", 4)
		.put("Desert", 5)
		.put("Lumbridge & Draynor", 6)
		.put("Morytania", 7)
		.put("Varrock", 8)
		.put("Wilderness", 9)
		.put("Western Provinces", 10)
		.put("Kourend & Kebos", 11)
		.build();

	@Inject
	private ClientThread clientThread;

	private final Map<AchievementDiary, Integer> snapshot = new EnumMap<>(AchievementDiary.class);
	private final Map<AchievementDiary, Integer> lastPostedTick = new EnumMap<>(AchievementDiary.class);
	private int ticksUntilSnapshot = SNAPSHOT_DELAY_TICKS;

	@Override
	public void reset()
	{
		snapshot.clear();
		lastPostedTick.clear();
		ticksUntilSnapshot = SNAPSHOT_DELAY_TICKS;
	}

	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			reset();
		}
	}

	public void onGameTick()
	{
		if (!snapshot.isEmpty() || --ticksUntilSnapshot > 0)
		{
			return;
		}

		for (AchievementDiary diary : AchievementDiary.values())
		{
			snapshot.put(diary, client.getVarbitValue(diary.getVarbit()));
		}
	}

	public void onVarbitChanged(VarbitChanged event)
	{
		AchievementDiary diary = AchievementDiary.fromVarbit(event.getVarbitId());
		if (diary == null || snapshot.isEmpty())
		{
			return;
		}

		int value = event.getValue();
		int previous = snapshot.get(diary);
		if (value < previous)
		{
			// Shouldn't happen, but it would post again when the value came back
			reset();
			return;
		}

		snapshot.put(diary, value);
		if (!diary.isComplete(previous) && diary.isComplete(value))
		{
			notifyCompleted(diary);
		}
	}

	public void onMessageBox(String message)
	{
		AchievementDiary diary = parse(message);
		if (diary == null)
		{
			return;
		}

		if (!snapshot.isEmpty())
		{
			// The varbit can land after this message
			snapshot.put(diary, diary.getCompleteValue());
		}
		notifyCompleted(diary);
	}

	private void notifyCompleted(AchievementDiary diary)
	{
		if (!config.includeDiaries() || diary.getDifficulty().ordinal() < config.minDiaryDifficulty().ordinal())
		{
			return;
		}

		int tick = client.getTickCount();
		Integer lastPosted = lastPostedTick.put(diary, tick);
		if (lastPosted != null && tick - lastPosted < COOLDOWN_TICKS)
		{
			return;
		}

		// Scripts can't safely run from inside these events
		clientThread.invokeLater(() -> sendCompleted(diary));
	}

	private void sendCompleted(AchievementDiary diary)
	{
		int areaId = SCRIPT_AREA_IDS.get(diary.getArea());
		send(NotificationType.DIARY, config.diaryMessage(),
			placeholders(diary, totalCompleted(diary, client::getVarbitValue),
				runIntScript(COMPLETED_TASKS_SCRIPT), runIntScript(TOTAL_TASKS_SCRIPT),
				runIntScript(COMPLETED_AREA_TASKS_SCRIPT, areaId), runIntScript(TOTAL_AREA_TASKS_SCRIPT, areaId)),
			config.sendDiaryScreenshot());
	}

	private int runIntScript(Object... args)
	{
		client.runScript(args);
		return client.getIntStack()[0];
	}

	static AchievementDiary parse(String message)
	{
		Matcher matcher = COMPLETION_REGEX.matcher(message);
		if (!matcher.find())
		{
			return null;
		}

		DiaryDifficulty difficulty = DiaryDifficulty.fromName(matcher.group("difficulty"));
		return difficulty == null ? null : AchievementDiary.find(difficulty, matcher.group("area").trim());
	}

	// The varbit for the one just finished may not have landed yet
	static int totalCompleted(AchievementDiary justCompleted, IntUnaryOperator varbits)
	{
		int total = 0;
		for (AchievementDiary diary : AchievementDiary.values())
		{
			if (diary == justCompleted || diary.isComplete(varbits.applyAsInt(diary.getVarbit())))
			{
				total++;
			}
		}
		return total;
	}

	static Map<String, String> placeholders(AchievementDiary diary, int totalDiaries, int tasksComplete, int tasksTotal, int areaTasksComplete, int areaTasksTotal)
	{
		return ImmutableMap.<String, String>builder()
			.put("area", diary.getArea())
			.put("difficulty", diary.getDifficulty().toString())
			.put("totalDiaries", String.valueOf(totalDiaries))
			.put("tasksComplete", String.valueOf(tasksComplete))
			.put("tasksTotal", String.valueOf(tasksTotal))
			.put("areaTasksComplete", String.valueOf(areaTasksComplete))
			.put("areaTasksTotal", String.valueOf(areaTasksTotal))
			.build();
	}
}

package com.discordnotifications.notifiers;

import lombok.extern.slf4j.Slf4j;

import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BooleanSupplier;

@Slf4j
@Singleton
public class HeldNotifications
{
	static final int MAX_TICKS = 10;

	private final List<Held> held = new ArrayList<>();

	void add(BooleanSupplier delivery)
	{
		held.add(new Held(delivery));
	}

	public void onGameTick()
	{
		held.removeIf(Held::finished);
	}

	public void reset()
	{
		held.clear();
	}

	private static class Held
	{
		final BooleanSupplier delivery;
		int ticks;

		Held(BooleanSupplier delivery)
		{
			this.delivery = delivery;
		}

		boolean finished()
		{
			if (delivery.getAsBoolean())
			{
				return true;
			}

			if (++ticks < MAX_TICKS)
			{
				return false;
			}

			log.debug("Dropping notification, local player name not available after {} ticks", MAX_TICKS);
			return true;
		}
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.BossNames;
import com.discordnotifications.KillCountService;
import com.discordnotifications.NotificationType;
import com.google.common.collect.ImmutableMap;
import lombok.Value;
import net.runelite.api.gameval.VarbitID;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Singleton
public class KillCountNotifier extends BaseNotifier
{
	private static final Pattern TIME_REGEX = Pattern.compile("(?:Duration|time|Subdued in):? (?<time>[\\d:]+(?:\\.\\d+)?)\\.?(?: Personal best: (?<pbtime>[\\d:+]+(?:\\.\\d+)?))?", Pattern.CASE_INSENSITIVE);
	private static final String NEW_BEST = "(new personal best)";
	private static final String RAID_COMPLETE = "Congratulations - your raid is complete!";
	private static final String TOB = "Theatre of Blood";
	private static final int MAX_WAIT_TICKS = 10;

	@Inject
	private KillCountService killCountService;

	private Kill pending;
	private int ticksWaited;

	@Override
	public void reset()
	{
		pending = null;
		ticksWaited = 0;
	}

	public void onGameMessage(String message, BossNames.BossKc kc)
	{
		Kill parsed = parse(message, kc);
		if (parsed != null)
		{
			pending = pending == null ? parsed : pending.merge(parsed);
		}
	}

	// CoX sends its time as a friends chat notification
	public void onFriendsChatNotification(String message)
	{
		if (message.startsWith(RAID_COMPLETE))
		{
			onGameMessage(message, null);
		}
	}

	public void onGameTick()
	{
		if (pending == null)
		{
			return;
		}

		// A milestone doesn't wait for a time, plenty of bosses never send one
		if (pending.getCount() != null && (pending.getTime() != null || isMilestone(pending.getCount())))
		{
			post(pending);
			reset();
		}
		else if (++ticksWaited > MAX_WAIT_TICKS)
		{
			reset();
		}
	}

	private void post(Kill kill)
	{
		boolean best = kill.isPersonalBest() && config.notifyPersonalBests();
		if (!config.includeKillCounts() || (!best && !isMilestone(kill.getCount())))
		{
			return;
		}

		send(NotificationType.KILL_COUNT, best ? config.personalBestMessage() : config.killCountMessage(),
			placeholders(kill, resolvePb(kill)),
			config.sendKillCountScreenshot());
	}

	private String resolvePb(Kill kill)
	{
		if (kill.getPb() != null || kill.isPersonalBest())
		{
			return kill.getPb();
		}
		return storedPbText(killCountService.getPb(kill.getBoss()), kill.getTime(), client.getVarbitValue(VarbitID.OPTION_PRECISE_TIMING) > 0);
	}

	private boolean isMilestone(int count)
	{
		return isMilestone(count, config.killCountInterval(), config.notifyFirstKill());
	}

	static boolean isMilestone(int count, int interval, boolean notifyFirst)
	{
		return (count == 1 && notifyFirst) || (interval > 0 && count % interval == 0);
	}

	static Kill parse(String message, BossNames.BossKc kc)
	{
		if (message.startsWith("Preparation"))
		{
			return null;
		}

		if (kc != null)
		{
			return new Kill(kc.getBoss(), kc.getCount(), null, false, null);
		}

		// TOB puts the last wave's duration before the raid's time in the same message
		int tob = message.startsWith("Wave") ? message.indexOf(TOB) : -1;
		String text = tob < 0 ? message : message.substring(tob);
		Matcher matcher = TIME_REGEX.matcher(text);
		if (!matcher.find())
		{
			return null;
		}

		return new Kill(tob < 0 ? null : TOB, null, matcher.group("time"), text.toLowerCase(Locale.ROOT).contains(NEW_BEST), matcher.group("pbtime"));
	}

	// A stored best that doesn't beat this kill is stale or from another team size
	static String storedPbText(Double stored, String time, boolean precise)
	{
		if (stored == null || (time != null && stored >= toSeconds(time)))
		{
			return null;
		}
		return formatTime(stored, precise);
	}

	private static double toSeconds(String time)
	{
		double seconds = 0;
		for (String part : time.split(":"))
		{
			seconds = seconds * 60 + Double.parseDouble(part);
		}
		return seconds;
	}

	static String formatTime(double seconds, boolean precise)
	{
		long hundredths = Math.round(seconds * 100);
		long whole = hundredths / 100;
		String time = whole >= 3600
			? String.format(Locale.ROOT, "%d:%02d:%02d", whole / 3600, whole / 60 % 60, whole % 60)
			: String.format(Locale.ROOT, "%d:%02d", whole / 60, whole % 60);
		return precise ? time + String.format(Locale.ROOT, ".%02d", hundredths % 100) : time;
	}

	static Map<String, String> placeholders(Kill kill, String pb)
	{
		return ImmutableMap.of(
			"boss", kill.getBoss(),
			"kc", KillCountService.kcText(kill.getCount()),
			"time", kill.getTime() == null ? "" : " in " + kill.getTime(),
			"pb", pb == null ? "" : " (PB " + pb + ")");
	}

	@Value
	static class Kill
	{
		String boss;
		Integer count;
		String time;
		boolean personalBest;
		String pb;

		Kill merge(Kill next)
		{
			String mergedBoss = next.boss != null ? next.boss : boss;
			// TOB sends the challenge time first and then a total time, the first is the one that counts
			boolean keepTime = next.time == null || (time != null && mergedBoss != null && mergedBoss.startsWith(TOB));
			return new Kill(mergedBoss,
				next.count != null ? next.count : count,
				keepTime ? time : next.time,
				keepTime ? personalBest : next.personalBest,
				keepTime ? pb : next.pb);
		}
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.LeagueTaskTier;
import com.discordnotifications.NotificationType;
import com.google.common.collect.ImmutableMap;
import lombok.RequiredArgsConstructor;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.StructComposition;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
@Singleton
public class LeaguesNotifier extends BaseNotifier
{
	private static final int LEAGUES_ENUM = 2670;
	private static final int TROPHY_THRESHOLDS_PARAM = 1857;
	private static final int RELIC_TIERS_PARAM = 870;
	private static final int TIER_RELICS_PARAM = 878;
	private static final int RELIC_NAME_PARAM = 879;
	private static final String[] TROPHIES = {"Bronze", "Iron", "Steel", "Mithril", "Adamant", "Rune", "Dragon"};

	public void onGameMessage(String message)
	{
		Event event = parse(message);
		if (event == null || !config.includeLeagues() || !onLeagueWorld())
		{
			return;
		}

		String template = templateFor(event);
		if (template == null)
		{
			return;
		}

		send(NotificationType.LEAGUES, template, withGameDetails(event), config.sendLeaguesScreenshot());
	}

	private boolean onLeagueWorld()
	{
		return client.getWorldType().contains(WorldType.SEASONAL) && client.getVarbitValue(VarbitID.LEAGUE_TYPE) > 0;
	}

	private String templateFor(Event event)
	{
		switch (event.getKind())
		{
			case AREA:
				return config.leaguesAreas() ? config.leaguesAreaMessage() : null;
			case RELIC:
				return config.leaguesRelics() ? config.leaguesRelicMessage() : null;
			case MASTERY:
				return config.leaguesMasteries() ? config.leaguesMasteryMessage() : null;
			default:
				return config.leaguesTasks() && event.getTier().ordinal() >= config.minLeaguesTaskTier().ordinal() ? config.leaguesTaskMessage() : null;
		}
	}

	private Map<String, String> withGameDetails(Event event)
	{
		Map<String, String> values = new HashMap<>(placeholders(event));
		// The struct ids can move between leagues, that shouldn't cost the player their post
		try
		{
			if (event.getKind() == Kind.RELIC)
			{
				int tier = relicTier(event.getName());
				if (tier > 0)
				{
					values.put("relicTier", " (Tier " + tier + ")");
				}
			}
			else if (event.getKind() == Kind.TASK)
			{
				int[] thresholds = client.getEnum(leagueStruct().getIntValue(TROPHY_THRESHOLDS_PARAM)).getIntVals();
				String trophy = earnedTrophy(thresholds, client.getVarpValue(VarPlayerID.LEAGUE_POINTS_COMPLETED), event.getTier().getPoints());
				if (trophy != null)
				{
					values.put("trophy", ", unlocking the " + trophy + " trophy");
				}
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Could not read league details for {}", event, e);
		}
		return values;
	}

	private StructComposition leagueStruct()
	{
		int[] leagues = client.getEnum(LEAGUES_ENUM).getIntVals();
		return client.getStructComposition(leagues[client.getVarbitValue(VarbitID.LEAGUE_TYPE) - 1]);
	}

	private int relicTier(String relic)
	{
		int[] tiers = client.getEnum(leagueStruct().getIntValue(RELIC_TIERS_PARAM)).getIntVals();
		for (int i = 0; i < tiers.length; i++)
		{
			int relics = client.getStructComposition(tiers[i]).getIntValue(TIER_RELICS_PARAM);
			for (int id : client.getEnum(relics).getIntVals())
			{
				if (relic.equals(client.getStructComposition(id).getStringValue(RELIC_NAME_PARAM)))
				{
					return i + 1;
				}
			}
		}
		return 0;
	}

	static String earnedTrophy(int[] thresholds, int points, int taskPoints)
	{
		String earned = null;
		for (int i = 0; i < Math.min(thresholds.length, TROPHIES.length); i++)
		{
			if (points >= thresholds[i] && points - taskPoints < thresholds[i])
			{
				earned = TROPHIES[i];
			}
		}
		return earned;
	}

	static Event parse(String message)
	{
		for (Kind kind : Kind.values())
		{
			Matcher matcher = kind.regex.matcher(message);
			if (!matcher.find())
			{
				continue;
			}

			if (kind != Kind.TASK)
			{
				return new Event(kind, matcher.group("name"), null);
			}

			LeagueTaskTier tier = LeagueTaskTier.fromName(matcher.group("tier"));
			return tier == null ? null : new Event(kind, matcher.group("name"), tier);
		}
		return null;
	}

	static Map<String, String> placeholders(Event event)
	{
		String key = event.getKind().placeholder;
		return event.getTier() == null
			? ImmutableMap.of(key, event.getName())
			: ImmutableMap.of(key, event.getName(), "tier", event.getTier().toString());
	}

	@RequiredArgsConstructor
	enum Kind
	{
		AREA("area", Pattern.compile("Congratulations, you've unlocked a new area: (?<name>.+)\\.")),
		RELIC("relic", Pattern.compile("Congratulations, you've unlocked a new Relic: (?<name>.+)\\.")),
		TASK("task", Pattern.compile("Congratulations, you've completed an? (?<tier>\\w+) task: (?<name>.+)\\.")),
		MASTERY("mastery", Pattern.compile("Congratulations, you've unlocked a new .+ Combat Mastery: (?<name>.+)\\."));

		private final String placeholder;
		private final Pattern regex;
	}

	@Value
	static class Event
	{
		Kind kind;
		String name;
		LeagueTaskTier tier;
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.NotificationType;
import com.discordnotifications.WorldUtils;
import com.google.common.collect.ImmutableMap;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.events.StatChanged;
import net.runelite.client.util.QuantityFormatter;

import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

@Singleton
public class LevelNotifier extends BaseNotifier
{
	// Stats aren't reliable for the first few seconds after login
	private static final int SETTLE_TICKS = 16;
	// Virtual levels stop at 126, so 200M XP gets treated as one more
	static final int MAX_XP_LEVEL = Experience.MAX_VIRT_LEVEL + 1;
	private static final String COMBAT = "Combat";

	private final Map<String, Integer> currentLevels = new HashMap<>();
	private final Set<String> leveledSkills = new LinkedHashSet<>();
	private boolean shouldSendLevelMessage = false;
	private int ticksWaited = 0;
	private int settleTicks = 0;
	private Set<WorldType> seededWorldTypes = null;

	@Override
	public void reset()
	{
		currentLevels.clear();
		leveledSkills.clear();
		shouldSendLevelMessage = false;
		ticksWaited = 0;
		settleTicks = 0;
		seededWorldTypes = null;
	}

	public void onStatChanged(StatChanged statChanged)
	{
		resetIfWorldChanged();

		int xp = statChanged.getXp();
		if (currentLevels.isEmpty() || xp <= 0 || statChanged.getLevel() <= 1)
		{
			return;
		}

		String skillName = statChanged.getSkill().getName();
		int newLevel = virtualLevel(statChanged.getLevel(), xp);
		int previousLevel = currentLevels.put(skillName, newLevel);

		if (newLevel < previousLevel)
		{
			// Levels can't go down, so what we seeded was wrong. Start over.
			reset();
			return;
		}

		if (newLevel == previousLevel)
		{
			return;
		}

		int previousCombat = currentLevels.get(COMBAT);
		int combat = combatLevel();
		currentLevels.put(COMBAT, combat);

		if (!config.includeLevelling())
		{
			return;
		}

		queueLevelUp(skillName, previousLevel, newLevel, config.notifyVirtualLevels());
		if (config.notifyCombatLevel())
		{
			queueLevelUp(COMBAT, previousCombat, combat, true);
		}
	}

	public void onGameTick()
	{
		resetIfWorldChanged();

		if (currentLevels.isEmpty())
		{
			if (++settleTicks >= SETTLE_TICKS)
			{
				seedLevels();
			}
			return;
		}

		if (!shouldSendLevelMessage)
		{
			return;
		}

		if (ticksWaited < 2)
		{
			ticksWaited++;
			return;
		}

		shouldSendLevelMessage = false;
		ticksWaited = 0;
		sendLevelMessage();
	}

	// Hopping to a world with its own stats (Leagues, speedrun) would look like a level up
	private void resetIfWorldChanged()
	{
		Set<WorldType> worldTypes = WorldUtils.separateStatsTypes(client.getWorldType());
		if (!worldTypes.equals(seededWorldTypes))
		{
			reset();
			seededWorldTypes = worldTypes;
		}
	}

	private void seedLevels()
	{
		for (Skill skill : Skill.values())
		{
			currentLevels.put(skill.getName(), virtualLevel(client.getRealSkillLevel(skill), client.getSkillExperience(skill)));
		}
		currentLevels.put(COMBAT, combatLevel());
	}

	private void queueLevelUp(String name, int previousLevel, int newLevel, boolean allowVirtual)
	{
		// Certain activities can multilevel
		for (int level = previousLevel + 1; level <= newLevel; level++)
		{
			if (shouldSendForThisLevel(level, allowVirtual))
			{
				leveledSkills.add(name);
				shouldSendLevelMessage = true;
				break;
			}
		}
	}

	private boolean shouldSendForThisLevel(int level, boolean allowVirtual)
	{
		return (allowVirtual || level <= Experience.MAX_REAL_LEVEL)
			&& level >= config.minLevel()
			&& meetsInterval(level, config.levelInterval(), config.levelIntervalOverride());
	}

	static boolean meetsInterval(int level, int interval, int override)
	{
		return interval <= 1
			|| level == Experience.MAX_REAL_LEVEL
			|| level == MAX_XP_LEVEL
			|| (override > 0 && level >= override)
			|| level % interval == 0;
	}

	static int virtualLevel(int level, int xp)
	{
		if (level < Experience.MAX_REAL_LEVEL)
		{
			return level;
		}
		return xp >= Experience.MAX_SKILL_XP ? MAX_XP_LEVEL : Experience.getLevelForXp(xp);
	}

	private int combatLevel()
	{
		return Experience.getCombatLevel(
			realLevel(Skill.ATTACK),
			realLevel(Skill.STRENGTH),
			realLevel(Skill.DEFENCE),
			realLevel(Skill.HITPOINTS),
			realLevel(Skill.MAGIC),
			realLevel(Skill.RANGED),
			realLevel(Skill.PRAYER));
	}

	private int realLevel(Skill skill)
	{
		return Math.min(currentLevels.get(skill.getName()), Experience.MAX_REAL_LEVEL);
	}

	private void sendLevelMessage()
	{
		Map<String, Integer> levels = new LinkedHashMap<>();
		for (String skill : leveledSkills)
		{
			levels.put(skill, currentLevels.get(skill));
		}
		leveledSkills.clear();

		send(NotificationType.LEVEL, config.levelMessage(),
			levelPlaceholders(levels, client.getTotalLevel(), currentLevels.get(COMBAT), client.getOverallExperience()),
			config.sendLevellingScreenshot());
	}

	static Map<String, String> levelPlaceholders(Map<String, Integer> levels, int totalLevel, int combatLevel, long totalXp)
	{
		List<String> skills = new ArrayList<>();
		for (Map.Entry<String, Integer> entry : levels.entrySet())
		{
			skills.add(entry.getKey() + " to " + displayLevel(entry.getValue()));
		}

		int last = skills.size() - 1;
		String joined = last == 0
			? skills.get(0)
			: String.join(", ", skills.subList(0, last)) + " and " + skills.get(last);

		Map.Entry<String, Integer> first = levels.entrySet().iterator().next();
		return ImmutableMap.<String, String>builder()
			.put("skills", joined)
			.put("skill", first.getKey())
			.put("level", displayLevel(first.getValue()))
			.put("total", Integer.toString(totalLevel))
			.put("totalXp", QuantityFormatter.formatNumber(totalXp))
			.put("combat", Integer.toString(combatLevel))
			.build();
	}

	private static String displayLevel(int level)
	{
		return level >= MAX_XP_LEVEL ? "Max XP" : Integer.toString(level);
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.DangerLevel;
import com.discordnotifications.ItemStackFormatter;
import com.discordnotifications.KillCountService;
import com.discordnotifications.LootValueBasis;
import com.discordnotifications.Notification;
import com.discordnotifications.NotificationType;
import com.discordnotifications.WildcardList;
import com.discordnotifications.WorldUtils;
import com.google.common.collect.ImmutableMap;
import lombok.Value;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.http.api.loottracker.LootRecordType;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;
import java.util.stream.Collectors;

@Singleton
public class LootNotifier extends BaseNotifier
{
	private static final String BA_GAMBLE = "Barbarian Assault high gamble";
	private static final String CLUE_SCROLL = "Clue Scroll";
	private static final String LOOT_CHEST = "Loot Chest";
	private static final String TRAWLING = "Deep sea trawling";

	// Core has no loot event for these, the chat line is all there is
	static final Map<String, ChatDrop> CHAT_DROPS = ImmutableMap.<String, ChatDrop>builder()
		.put("You have found a Pharaoh's sceptre! It fell on the floor.", new ChatDrop(ItemID.PHARAOHS_SCEPTRE, "Pyramid Plunder"))
		.put("You catch a giant blue krill!", new ChatDrop(ItemID.POH_TROPHYDROP_GIANT_KRILL, TRAWLING))
		.put("You catch a golden haddock!", new ChatDrop(ItemID.POH_TROPHYDROP_HADDOCK, TRAWLING))
		.put("You catch a orangefin!", new ChatDrop(ItemID.POH_TROPHYDROP_YELLOWFIN, TRAWLING))
		.put("You catch a huge halibut!", new ChatDrop(ItemID.POH_TROPHYDROP_HALIBUT, TRAWLING))
		.put("You catch a purplefin!", new ChatDrop(ItemID.POH_TROPHYDROP_BLUEFIN, TRAWLING))
		.put("You catch a swift marlin!", new ChatDrop(ItemID.POH_TROPHYDROP_MARLIN, TRAWLING))
		.build();

	@Inject
	private ItemStackFormatter itemStackFormatter;

	@Inject
	private KillCountService killCountService;

	@Inject
	private ChatMessageManager chatMessageManager;

	private final List<PendingLoot> pendingEventLoot = new ArrayList<>();
	private Map<Integer, Integer> wornLastTick = Collections.emptyMap();
	private boolean warnedLootTrackerOff;

	@Override
	public void reset()
	{
		pendingEventLoot.clear();
		wornLastTick = Collections.emptyMap();
	}

	public void onGameTick()
	{
		flushEventLoot();

		if (warnedLootTrackerOff || !config.includeLoot() || !killCountService.lootTrackerDisabled())
		{
			return;
		}

		warnedLootTrackerOff = true;
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage("Discord Notifications: turn on the Loot Tracker plugin to get notified for raids, chests and pickpocketing.")
			.build());
	}

	public void onNpcLootReceived(NpcLootReceived event)
	{
		if (config.includeLoot())
		{
			handleLoot(event.getItems(), event.getNpc().getName(), LootRecordType.NPC);
		}
	}

	public void onServerNpcLoot(ServerNpcLoot event)
	{
		if (config.includeLoot())
		{
			handleLoot(event.getItems(), event.getComposition().getName(), LootRecordType.NPC);
		}
	}

	public void onGameMessage(String message)
	{
		ChatDrop drop = CHAT_DROPS.get(message);
		if (drop != null && config.includeLoot())
		{
			handleLoot(Collections.singletonList(new ItemStack(drop.getItemId(), 1)), drop.getSource(), LootRecordType.EVENT);
		}
	}

	public void onPlayerLootReceived(PlayerLootReceived event)
	{
		String name = event.getPlayer().getName();
		if (config.includeLoot() && config.includePlayerLoot() && name != null && !inSafeArea())
		{
			handleLoot(event.getItems(), name, LootRecordType.PLAYER);
		}
	}

	public void onLootReceived(LootReceived event)
	{
		if (!config.includeLoot() || event.getName() == null || isSkippedEvent(event.getName()))
		{
			return;
		}

		// The loot tracker reposts every NPC and PvP kill, those came through the events above
		LootRecordType type = event.getType();
		if (type == LootRecordType.EVENT || type == LootRecordType.PICKPOCKET
			|| (type == LootRecordType.NPC && KillCountService.LOOT_RECEIVED_NPCS.contains(event.getName())))
		{
			String source = killCountService.getStandardizedSource(event);
			LootRecordType recordType = KillCountService.standardizedType(source, type);
			if (type == LootRecordType.EVENT)
			{
				// KC is read now, the loot tracker has saved this kill by the next tick
				pendingEventLoot.add(new PendingLoot(event.getItems(), source, killCountService.getKillCount(recordType, source)));
			}
			else
			{
				handleLoot(event.getItems(), source, recordType);
			}
		}
	}

	// Event loot is an inventory diff, so gear taken off on the same tick looks like loot
	private void flushEventLoot()
	{
		Map<Integer, Integer> worn = wornItems();
		Map<Integer, Integer> unequipped = removedItems(wornLastTick, worn);
		wornLastTick = worn;

		for (PendingLoot loot : pendingEventLoot)
		{
			handleLoot(withoutUnequipped(loot.getItems(), unequipped), loot.getSource(), LootRecordType.EVENT, loot::getKc);
		}
		pendingEventLoot.clear();
	}

	private Map<Integer, Integer> wornItems()
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn == null)
		{
			return Collections.emptyMap();
		}

		Map<Integer, Integer> quantities = new HashMap<>();
		for (Item item : worn.getItems())
		{
			if (item.getQuantity() > 0)
			{
				quantities.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return quantities;
	}

	static Map<Integer, Integer> removedItems(Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		Map<Integer, Integer> removed = new HashMap<>();
		before.forEach((id, quantity) ->
		{
			int gone = quantity - after.getOrDefault(id, 0);
			if (gone > 0)
			{
				removed.put(id, gone);
			}
		});
		return removed;
	}

	// Takes the count and not the whole stack, you can take off one tome and win another
	static List<ItemStack> withoutUnequipped(Collection<ItemStack> items, Map<Integer, Integer> unequipped)
	{
		List<ItemStack> kept = new ArrayList<>(items.size());
		for (ItemStack item : items)
		{
			int taken = Math.min(item.getQuantity(), unequipped.getOrDefault(item.getId(), 0));
			unequipped.merge(item.getId(), -taken, Integer::sum);
			if (item.getQuantity() > taken)
			{
				kept.add(new ItemStack(item.getId(), item.getQuantity() - taken));
			}
		}
		return kept;
	}

	private boolean inSafeArea()
	{
		Player player = client.getLocalPlayer();
		return player == null
			|| WorldUtils.getDangerLevel(client, WorldUtils.getLocation(client, player).getRegionID()) == DangerLevel.SAFE;
	}

	private void handleLoot(Collection<ItemStack> items, String source, LootRecordType type)
	{
		handleLoot(items, source, type, () -> killCountService.getKillCount(type, source));
	}

	private void handleLoot(Collection<ItemStack> items, String source, LootRecordType type, Supplier<Integer> kc)
	{
		if (isDeniedSource(source, type, WildcardList.parse(config.lootSourceDenylist())))
		{
			return;
		}

		Map<Integer, Integer> quantities = new LinkedHashMap<>();
		for (ItemStack item : items)
		{
			quantities.merge(item.getId(), item.getQuantity(), Integer::sum);
		}

		List<ItemStackFormatter.Stack> stacks = new ArrayList<>(quantities.size());
		quantities.forEach((id, quantity) -> stacks.add(itemStackFormatter.stackWithStorePrice(id, quantity)));

		List<ItemStackFormatter.Stack> qualifying = qualifying(stacks, source, config.minLootValue(), config.lootValueBasis(),
			WildcardList.parse(config.lootAllowlist()), WildcardList.parse(config.lootDenylist()));
		if (qualifying.isEmpty())
		{
			return;
		}

		send(Notification.builder()
			.type(NotificationType.LOOT)
			.text(config.lootMessage())
			.placeholders(placeholders(qualifying, stacks, sanitize(source), kc.get()))
			.itemNames(qualifying.stream().map(ItemStackFormatter.Stack::getName).collect(Collectors.toList()))
			.screenshot(config.sendLootScreenshot())
			.build());
	}

	static boolean isSkippedEvent(String name)
	{
		return name != null && (BA_GAMBLE.equals(name) || name.regionMatches(true, 0, CLUE_SCROLL, 0, CLUE_SCROLL.length()));
	}

	static boolean isDeniedSource(String source, LootRecordType type, WildcardList denylist)
	{
		return type != LootRecordType.PLAYER && denylist.matches(sanitize(source));
	}

	static List<ItemStackFormatter.Stack> qualifying(List<ItemStackFormatter.Stack> stacks, String source, long minValue, LootValueBasis basis, WildcardList allowlist, WildcardList denylist)
	{
		List<ItemStackFormatter.Stack> eligible = stacks.stream()
			.filter(stack -> !denylist.matches(stack.getName()))
			.collect(Collectors.toList());

		if (basis == LootValueBasis.DROP && ItemStackFormatter.totalValue(eligible) >= minValue)
		{
			return eligible;
		}

		List<ItemStackFormatter.Stack> qualifying = eligible.stream()
			.filter(stack -> allowlist.matches(stack.getName())
				|| (basis == LootValueBasis.ITEM ? stack.getUnitPrice() : stack.getTotalPrice()) >= minValue)
			.collect(Collectors.toList());

		return qualifying.isEmpty() && basis != LootValueBasis.DROP && LOOT_CHEST.equalsIgnoreCase(source)
			? lootChestStandIn(eligible, minValue)
			: qualifying;
	}

	// PK loot keys hold lots of small stacks, so the whole chest counts and its best stack gets listed
	static List<ItemStackFormatter.Stack> lootChestStandIn(List<ItemStackFormatter.Stack> stacks, long minValue)
	{
		if (ItemStackFormatter.totalValue(stacks) < minValue)
		{
			return Collections.emptyList();
		}

		return stacks.stream()
			.max(Comparator.comparingLong(ItemStackFormatter.Stack::getTotalPrice))
			.map(Collections::singletonList)
			.orElse(Collections.emptyList());
	}

	static Map<String, String> placeholders(List<ItemStackFormatter.Stack> qualifying, List<ItemStackFormatter.Stack> drop, String source, Integer kc)
	{
		Map<String, String> placeholders = new HashMap<>();
		placeholders.put("items", ItemStackFormatter.format(qualifying));
		placeholders.put("value", QuantityFormatter.quantityToStackSize(ItemStackFormatter.totalValue(drop)));
		placeholders.put("source", source);
		placeholders.put("kc", KillCountService.kcText(kc));
		return placeholders;
	}

	@Value
	private static class PendingLoot
	{
		Collection<ItemStack> items;
		String source;
		Integer kc;
	}

	@Value
	static class ChatDrop
	{
		int itemId;
		String source;
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.NotificationType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.KeyManager;
import net.runelite.client.util.HotkeyListener;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Collections;

@Singleton
public class ManualScreenshotNotifier extends BaseNotifier
{
	@Inject
	private KeyManager keyManager;

	@Inject
	private ClientThread clientThread;

	private final HotkeyListener hotkey = new HotkeyListener(() -> config.screenshotHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			// Key events aren't on the client thread, and capturing has to be
			clientThread.invokeLater(() -> send(NotificationType.MANUAL_SCREENSHOT, config.screenshotMessage(), Collections.emptyMap(), true));
		}
	};

	public void start()
	{
		keyManager.registerKeyListener(hotkey);
	}

	public void stop()
	{
		keyManager.unregisterKeyListener(hotkey);
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.KillCountService;
import com.discordnotifications.Notification;
import com.discordnotifications.NotificationType;
import com.google.common.collect.ImmutableList;
import com.google.common.collect.ImmutableSet;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.VarClientID;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Singleton
public class PetNotifier extends BaseNotifier
{
	static final Pattern PET_REGEX = Pattern.compile("You (?:have a funny feeling like you|feel something weird sneaking).*");
	static final Pattern CLAN_REGEX = Pattern.compile("\\b(?<user>[\\w\\s-]+) (?:has a funny feeling like .+ followed|feels something weird sneaking into .+ backpack|feels like .+ acquired something special): (?<pet>.+?)(?: at (?<milestone>.+?)\\.?)?$");

	private static final List<Pattern> NAME_SOURCES = ImmutableList.of(
		Pattern.compile("Untradeable drop: (.+)"),
		Pattern.compile("New item added to your collection log: (.+)"));

	private static final String NO_NAME_MESSAGE = "$name just got a pet$from$kc!$duplicate";
	private static final int MAX_WAIT_TICKS = 5;

	// Other untradeables can drop during the wait, "Pet ..." names are matched by prefix
	private static final Set<String> PET_NAMES = ImmutableSet.of(
		"abyssal orphan", "abyssal protector", "baby chinchompa", "baby mole", "baron", "beef",
		"bran", "butch", "beaver", "bloodhound", "callisto cub", "chompy chick", "dom",
		"giant squirrel", "hellpuppy", "herbi", "heron", "huberte", "ikkle hydra", "jal-nib-rek",
		"kalphite princess", "lil' creator", "lil' zik", "lil'viathan", "little nightmare",
		"maggot marquess", "moxi", "muphin", "nexling", "nid", "noon", "olmlet", "phoenix",
		"prince black dragon", "quetzin", "rift guardian", "rock golem", "rocky",
		"scorpia's offspring", "scurry", "skotos", "smolcano", "smol heredit", "soup", "sraracha",
		"tangleroot", "tiny tempor", "tumeken's guardian", "tzrek-jad", "venenatis spiderling",
		"vet'ion jr.", "vorki", "wisp", "yami", "youngllef");

	@Inject
	private KillCountService killCountService;

	private boolean waiting;
	private boolean duplicate;
	private String pet;
	private String milestone;
	private int ticksWaited;

	@Override
	public void reset()
	{
		waiting = false;
		duplicate = false;
		pet = null;
		milestone = null;
		ticksWaited = 0;
	}

	public void onGameMessage(String chatMessage)
	{
		if (waiting)
		{
			if (pet == null)
			{
				pet = parsePetName(chatMessage);
			}
			return;
		}

		if (!config.includePets() || !PET_REGEX.matcher(chatMessage).matches())
		{
			return;
		}

		boolean wouldHaveBeen = chatMessage.contains("would have been");
		if (!wouldHaveBeen || config.notifyDuplicatePets())
		{
			waiting = true;
			duplicate = wouldHaveBeen;
		}
	}

	public void onClanMessage(String message)
	{
		if (!waiting)
		{
			return;
		}

		Matcher matcher = CLAN_REGEX.matcher(message);
		if (matcher.find() && matcher.group("user").trim().equals(playerName()))
		{
			pet = matcher.group("pet");
			milestone = matcher.group("milestone");
		}
	}

	public void onScriptPreFired(ScriptPreFired event)
	{
		if (!waiting || pet != null || event.getScriptId() != ScriptID.NOTIFICATION_DELAY)
		{
			return;
		}

		String topText = sanitize(client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE));
		String entry = popupSubject(client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN));
		if (topText.equalsIgnoreCase("Collection log") && isPet(entry))
		{
			pet = entry;
		}
	}

	public void onGameTick()
	{
		if (!waiting)
		{
			return;
		}

		if ((pet != null && milestone != null) || ++ticksWaited > MAX_WAIT_TICKS)
		{
			if (config.includePets())
			{
				sendPet();
			}
			reset();
		}
	}

	private void sendPet()
	{
		Map<String, String> placeholders = new HashMap<>();
		if (pet != null)
		{
			placeholders.put("pet", pet);
		}
		KillCountService.Drop drop = killCountService.getRecentPetDrop();
		if (drop != null)
		{
			placeholders.putAll(KillCountService.sourcePlaceholders(sanitize(drop.getSource()), killCountService.getKillCount(drop.getType(), drop.getSource())));
		}
		if (milestone != null && placeholders.getOrDefault("kc", "").isEmpty())
		{
			placeholders.put("milestone", " at " + milestone);
		}
		if (duplicate)
		{
			placeholders.put("duplicate", " (would have been followed)");
		}

		String template = config.petMessage();
		boolean noName = pet == null && template.contains("$pet");
		send(Notification.builder()
			.type(NotificationType.PET)
			.text(noName ? NO_NAME_MESSAGE : template)
			// A duplicate never fills a collection log slot, so any clog line beside it is another item
			.namedText(pet == null && !duplicate ? template : null)
			.placeholders(placeholders)
			.screenshot(config.sendPetScreenshot())
			.build());
	}

	static String parsePetName(String message)
	{
		for (Pattern source : NAME_SOURCES)
		{
			Matcher matcher = source.matcher(message);
			if (matcher.find() && isPet(matcher.group(1)))
			{
				return matcher.group(1);
			}
		}
		return null;
	}

	static boolean isPet(String itemName)
	{
		String name = itemName.toLowerCase();
		return name.startsWith("pet ") || PET_NAMES.contains(name);
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.NotificationType;
import com.google.common.collect.ImmutableList;
import com.google.common.collect.ImmutableMap;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Singleton
public class QuestNotifier extends BaseNotifier
{
	private static final Pattern QUEST_PATTERN_1 = Pattern.compile(".+?ve\\.*? (?<verb>been|rebuilt|.+?ed)? ?(?:the )?'?(?<quest>.+?)'?(?: quest)?[!.]?$", Pattern.CASE_INSENSITIVE);
	private static final Pattern QUEST_PATTERN_2 = Pattern.compile("'?(?<quest>.+?)'?(?: quest)? (?<verb>[a-z]\\w+?ed)?(?: f.*?)?[!.]?$", Pattern.CASE_INSENSITIVE);
	private static final ImmutableList<String> RFD_TAGS = ImmutableList.of("Another Cook", "freed", "defeated", "saved");
	private static final ImmutableList<String> WORD_QUEST_IN_NAME_TAGS =
		ImmutableList.of(
			"Another Cook",
			"Doric",
			"Heroes",
			"Legends",
			"Observatory",
			"Olaf",
			"Waterfall"
		);

	private static final ImmutableMap<String, String> QUEST_REPLACEMENTS =
		ImmutableMap.of(
			"Lumbridge Cook... again", "Another Cook's",
			"Skrach 'Bone Crusher' Uglogwee", "Skrach Uglogwee"
		);

	@Inject
	private ClientThread clientThread;

	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() != InterfaceID.QUESTSCROLL || !config.includeQuestComplete())
		{
			return;
		}

		Widget title = client.getWidget(InterfaceID.Questscroll.QUEST_TITLE);
		if (title != null)
		{
			String text = sanitize(title.getText());
			// The quest varbits haven't updated yet when the scroll opens
			clientThread.invokeLater(() -> sendQuestMessage(text));
		}
	}

	private void sendQuestMessage(String text)
	{
		String questName = parseQuestCompletedWidget(text);
		if (questName == null)
		{
			return;
		}

		send(NotificationType.QUEST, config.questMessage(),
			placeholders(
				questName,
				client.getVarbitValue(VarbitID.QUESTS_COMPLETED_COUNT),
				client.getVarbitValue(VarbitID.QUESTS_TOTAL_COUNT),
				client.getVarpValue(VarPlayerID.QP),
				client.getVarbitValue(VarbitID.QP_MAX)),
			config.sendQuestingScreenshot());
	}

	static Map<String, String> placeholders(String quest, int completed, int totalQuests, int qp, int qpMax)
	{
		Map<String, String> placeholders = new HashMap<>();
		placeholders.put("quest", quest);

		if (completed > 0 && totalQuests > 0)
		{
			placeholders.put("completed", Integer.toString(completed));
			placeholders.put("totalQuests", Integer.toString(totalQuests));
		}

		if (qp > 0 && qpMax > 0)
		{
			placeholders.put("qp", Integer.toString(qp));
			placeholders.put("qpMax", Integer.toString(qpMax));
			placeholders.put("progress", " (" + qp + "/" + qpMax + " QP)");
		}

		return placeholders;
	}

	static String parseQuestCompletedWidget(final String text)
	{
		// "You have completed The Corsair Curse!"
		final Matcher questMatch1 = QUEST_PATTERN_1.matcher(text);
		// "'One Small Favour' completed!"
		final Matcher questMatch2 = QUEST_PATTERN_2.matcher(text);
		final Matcher questMatchFinal = questMatch1.matches() ? questMatch1 : questMatch2;

		if (!questMatchFinal.matches())
		{
			return text.isEmpty() ? null : text;
		}

		String quest = questMatchFinal.group("quest");
		quest = QUEST_REPLACEMENTS.getOrDefault(quest, quest);
		String verb = questMatchFinal.group("verb") != null ? questMatchFinal.group("verb") : "";

		if (verb.contains("kind of"))
		{
			return null;
		}
		else if (verb.contains("completely"))
		{
			quest += " II";
		}

		if (RFD_TAGS.stream().anyMatch((quest + verb)::contains))
		{
			quest = "Recipe for Disaster - " + quest;
		}

		if (WORD_QUEST_IN_NAME_TAGS.stream().anyMatch(quest::contains))
		{
			quest += " Quest";
		}

		return quest;
	}
}

