public class CombatAchievementNotifierTest
{
	private static final Map<CombatAchievementTier, Integer> THRESHOLDS = new EnumMap<>(CombatAchievementTier.class);

	static
	{
		THRESHOLDS.put(CombatAchievementTier.EASY, 33);
