		assertEquals("Iron", LeaguesNotifier.earnedTrophy(THRESHOLDS, 4_000, 10));
		assertEquals("Bronze", LeaguesNotifier.earnedTrophy(THRESHOLDS, 2_000, 400));
	}

	@Test
	public void noTrophyWhenThresholdAlreadyPassedOrNotReached()
	{
		assertNull(LeaguesNotifier.earnedTrophy(THRESHOLDS, 4_090, 80));
		assertNull(LeaguesNotifier.earnedTrophy(THRESHOLDS, 3_990, 80));
		assertNull(LeaguesNotifier.earnedTrophy(THRESHOLDS, 1_000, 10));
		assertNull(LeaguesNotifier.earnedTrophy(new int[0], 4_010, 80));
	}

	@Test
	public void ignoresThresholdsPastTheKnownTrophies()
	{
		assertNull(LeaguesNotifier.earnedTrophy(new int[]{1, 2, 3, 4, 5, 6, 7, 80_000}, 80_010, 80));
	}

	@Test
	public void rendersPlaceholders()
	{
		assertEquals("Hard The Frozen Door",
			Template.render("$tier $task", LeaguesNotifier.placeholders(LeaguesNotifier.parse("Congratulations, you've completed a hard task: The Frozen Door."))));
		assertEquals("Kandarin",
			Template.render("$area", LeaguesNotifier.placeholders(LeaguesNotifier.parse("Congratulations, you've unlocked a new area: Kandarin."))));
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.DiscordNotificationsConfig;
import com.discordnotifications.DiscordWebhookService;
import com.discordnotifications.Notification;
import com.discordnotifications.Template;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.events.StatChanged;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class LevelNotifierTest
{
	private static final int SETTLE_TICKS = 16;
	private static final int TICKS_TO_POST = 3;

	@Mock
	private Client client;

	@Mock
	private DiscordNotificationsConfig config;

	@Mock
	private DiscordWebhookService webhookService;

	@Mock
	private HeldNotifications heldNotifications;

	@Mock
	private Player player;

	@InjectMocks
	private LevelNotifier notifier;

	@Before
	public void setUp()
	{
		lenient().when(client.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
		lenient().when(client.getLocalPlayer()).thenReturn(player);
		lenient().when(player.getName()).thenReturn("Bob");
		lenient().when(client.getRealSkillLevel(any())).thenReturn(50);
		lenient().when(config.includeLevelling()).thenReturn(true);
		lenient().when(config.levelMessage()).thenReturn("$name: $skills");
	}

	private void ticks(int count)
	{
		for (int i = 0; i < count; i++)
		{
			notifier.onGameTick();
		}
	}

	private void stat(Skill skill, int level)
	{
		notifier.onStatChanged(new StatChanged(skill, Experience.getXpForLevel(level), level, level));
	}

	private void assertNothingPosted()
	{
		verify(webhookService, never()).send(any());
	}

	private void assertPosted(String text)
	{
		ArgumentCaptor<Notification> sent = ArgumentCaptor.forClass(Notification.class);
		verify(webhookService).send(sent.capture());
		assertEquals(text, sent.getValue().getText());
	}

	@Test
	public void statsAreIgnoredUntilTheyHaveSettled()
	{
		ticks(SETTLE_TICKS - 1);
		stat(Skill.ATTACK, 51);
		ticks(1 + TICKS_TO_POST);
		assertNothingPosted();

		stat(Skill.ATTACK, 51);
		ticks(TICKS_TO_POST);
		assertPosted("Bob: Attack to 51");
	}

	@Test
	public void seededLevelIsNotALevelUp()
	{
		ticks(SETTLE_TICKS);
		stat(Skill.ATTACK, 50);
		ticks(TICKS_TO_POST);
		assertNothingPosted();
	}

	@Test
	public void seedsVirtualLevelsFromXp()
	{
		int xp = Experience.getXpForLevel(100);
		when(client.getRealSkillLevel(Skill.ATTACK)).thenReturn(99);
		when(client.getSkillExperience(Skill.ATTACK)).thenReturn(xp);
		lenient().when(config.notifyVirtualLevels()).thenReturn(true);

		ticks(SETTLE_TICKS);
		notifier.onStatChanged(new StatChanged(Skill.ATTACK, xp, 99, 99));
		ticks(TICKS_TO_POST);
		assertNothingPosted();
	}

	@Test
	public void waitsSoSkillsLevelledTogetherShareALine()
	{
		ticks(SETTLE_TICKS);
		stat(Skill.ATTACK, 51);
		ticks(1);
		stat(Skill.STRENGTH, 51);
		ticks(1);
		assertNothingPosted();

		ticks(1);
		assertPosted("Bob: Attack to 51 and Strength to 51");
	}

	@Test
	public void levelBelowTheSeedStartsOver()
	{
		ticks(SETTLE_TICKS);
		stat(Skill.ATTACK, 40);

		stat(Skill.ATTACK, 51);
		ticks(SETTLE_TICKS - 1);
		assertNothingPosted();

		ticks(1);
		stat(Skill.ATTACK, 51);
		ticks(TICKS_TO_POST);
		assertPosted("Bob: Attack to 51");
	}

	@Test
	public void resetDropsThePendingPostAndTheSeed()
	{
		ticks(SETTLE_TICKS);
		stat(Skill.ATTACK, 51);
		notifier.reset();

		ticks(TICKS_TO_POST);
		stat(Skill.ATTACK, 52);
		ticks(TICKS_TO_POST);
		assertNothingPosted();
	}

	@Test
	public void hoppingToAWorldWithItsOwnStatsReseeds()
	{
		ticks(SETTLE_TICKS);
		when(client.getWorldType()).thenReturn(EnumSet.of(WorldType.SEASONAL));
		stat(Skill.ATTACK, 51);
		ticks(TICKS_TO_POST);
		assertNothingPosted();
	}

	@Test
	public void hoppingBetweenNormalWorldsKeepsTheSeed()
	{
		ticks(SETTLE_TICKS);
		when(client.getWorldType()).thenReturn(EnumSet.of(WorldType.MEMBERS));
		stat(Skill.ATTACK, 51);
		ticks(TICKS_TO_POST);
		assertPosted("Bob: Attack to 51");
	}

	private static Map<String, Integer> levels(Object... skillsAndLevels)
	{
		Map<String, Integer> levels = new LinkedHashMap<>();
		for (int i = 0; i < skillsAndLevels.length; i += 2)
		{
			levels.put((String) skillsAndLevels[i], (Integer) skillsAndLevels[i + 1]);
		}
		return levels;
	}

	private static String render(String template, Map<String, Integer> levels)
	{
		return Template.render(template, LevelNotifier.levelPlaceholders(levels, 1500, 88, 4_600_000_000L));
	}

	@Test
	public void oneSkill()
	{
		assertEquals("Attack to 70 / 1500", render("$skills / $total", levels("Attack", 70)));
	}

	@Test
	public void twoSkills()
	{
		assertEquals("Attack to 70 and Hitpoints to 71",
			render("$skills", levels("Attack", 70, "Hitpoints", 71)));
	}

	@Test
	public void threeSkillsKeepOrder()
	{
		assertEquals("Attack to 70, Strength to 72 and Hitpoints to 71",
			render("$skills", levels("Attack", 70, "Strength", 72, "Hitpoints", 71)));
	}

	@Test
	public void oldPlaceholdersGiveTheFirstSkill()
	{
		assertEquals("Attack to 70", render("$skill to $level", levels("Attack", 70, "Hitpoints", 71)));
	}

	@Test
	public void combatPlaceholder()
	{
		assertEquals("Combat to 88 / 88", render("$skills / $combat", levels("Combat", 88)));
	}

	@Test
	public void totalXpPlaceholder()
	{
		assertEquals("1500 / 4,600,000,000", render("$total / $totalXp", levels("Attack", 70)));
	}

	@Test
	public void maxXpReadsAsWords()
	{
		assertEquals("Attack to Max XP", render("$skills", levels("Attack", LevelNotifier.MAX_XP_LEVEL)));
		assertEquals("Attack Max XP", render("$skill $level", levels("Attack", LevelNotifier.MAX_XP_LEVEL)));
	}

	@Test
	public void virtualLevels()
	{
		assertEquals(98, LevelNotifier.virtualLevel(98, 12_000_000));
		assertEquals(99, LevelNotifier.virtualLevel(99, 13_034_431));
		assertEquals(100, LevelNotifier.virtualLevel(99, 14_391_160));
		assertEquals(126, LevelNotifier.virtualLevel(99, 199_999_999));
		assertEquals(LevelNotifier.MAX_XP_LEVEL, LevelNotifier.virtualLevel(99, 200_000_000));
	}

	@Test
	public void intervalAndOverride()
	{
		assertTrue(LevelNotifier.meetsInterval(73, 1, 0));
		assertTrue(LevelNotifier.meetsInterval(70, 10, 0));
		assertFalse(LevelNotifier.meetsInterval(73, 10, 0));
		assertTrue(LevelNotifier.meetsInterval(99, 10, 0));
		assertTrue(LevelNotifier.meetsInterval(LevelNotifier.MAX_XP_LEVEL, 10, 0));

		assertFalse(LevelNotifier.meetsInterval(73, 10, 80));
		assertTrue(LevelNotifier.meetsInterval(80, 10, 80));
		assertTrue(LevelNotifier.meetsInterval(83, 10, 80));
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.ItemStackFormatter.Stack;
import com.discordnotifications.LootValueBasis;
import com.discordnotifications.Template;
import com.discordnotifications.WildcardList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.runelite.client.game.ItemStack;
import net.runelite.http.api.loottracker.LootRecordType;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class LootNotifierTest
{
	private static final Stack WHIP = new Stack("Abyssal whip", 1, 1_500_000);
	private static final Stack LAWS = new Stack("Law rune", 10, 200);
	private static final Stack ONYX_TIPS = new Stack("Onyx bolt tips", 1_000, 9_000);
	private static final List<Stack> CHEST = Arrays.asList(new Stack("Shark", 50, 800), new Stack("Rune platebody", 1, 38_000), new Stack("Coins", 30_000, 1));

	private static List<Stack> qualifying(List<Stack> stacks, LootValueBasis basis, long minValue, String allowlist, String denylist)
	{
		return LootNotifier.qualifying(stacks, "Vorkath", minValue, basis, WildcardList.parse(allowlist), WildcardList.parse(denylist));
	}

	private static List<Stack> chestQualifying(LootValueBasis basis, long minValue, String denylist)
	{
		return LootNotifier.qualifying(CHEST, "Loot Chest", minValue, basis, WildcardList.parse(""), WildcardList.parse(denylist));
	}

	private static Map<Integer, Integer> kept(Map<Integer, Integer> unequipped, ItemStack... items)
	{
		return LootNotifier.withoutUnequipped(Arrays.asList(items), new HashMap<>(unequipped)).stream()
			.collect(Collectors.toMap(ItemStack::getId, ItemStack::getQuantity));
	}

	@Test
	public void removedItemsAreWhatLeftTheContainer()
	{
		assertEquals(Map.of(1, 1, 2, 30), LootNotifier.removedItems(Map.of(1, 1, 2, 100, 3, 1), Map.of(2, 70, 3, 1, 4, 1)));
	}

	@Test
	public void unequippedGearIsNotLoot()
	{
		assertEquals(Map.of(2, 5), kept(Map.of(1, 1), new ItemStack(1, 1), new ItemStack(2, 5)));
	}

	@Test
	public void onlyTheUnequippedCountIsSubtracted()
	{
		assertEquals(Map.of(1, 1), kept(Map.of(1, 1), new ItemStack(1, 2)));
	}

	@Test
	public void anUnequippedItemIsOnlySubtractedOnce()
	{
		Map<Integer, Integer> unequipped = new HashMap<>(Map.of(1, 1));
		assertTrue(LootNotifier.withoutUnequipped(List.of(new ItemStack(1, 1)), unequipped).isEmpty());
		assertEquals(1, LootNotifier.withoutUnequipped(List.of(new ItemStack(1, 1)), unequipped).size());
	}

	@Test
	public void onlyStacksOverTheMinimumQualify()
	{
		assertEquals(Collections.singletonList(WHIP), qualifying(Arrays.asList(WHIP, LAWS), LootValueBasis.STACK, 100_000, "", ""));
		assertTrue(qualifying(Collections.singletonList(LAWS), LootValueBasis.STACK, 100_000, "", "").isEmpty());
	}

	@Test
	public void minimumIsInclusive()
	{
		assertEquals(1, qualifying(Collections.singletonList(new Stack("Item", 1, 100_000)), LootValueBasis.STACK, 100_000, "", "").size());
		assertTrue(qualifying(Collections.singletonList(new Stack("Item", 1, 99_999)), LootValueBasis.STACK, 100_000, "", "").isEmpty());
	}

	@Test
	public void stackValueDoesNotOverflow()
	{
		Stack huge = new Stack("Item", 2_000_000, 5_000);
		assertEquals(10_000_000_000L, huge.getTotalPrice());
		assertEquals(1, qualifying(Collections.singletonList(huge), LootValueBasis.STACK, 100_000, "", "").size());
	}

	@Test
	public void itemsAreQualifyingStacksAndValueIsWholeDrop()
	{
		List<Stack> qualifying = Collections.singletonList(WHIP);
		assertEquals("1 x Abyssal whip (1.5M) from Vorkath (KC 1,234) worth 1.59M",
			Template.render("$items from $source$kc worth $value",
				LootNotifier.placeholders(qualifying, Arrays.asList(WHIP, new Stack("Coins", 90_000, 1)), "Vorkath", 1234)));
	}

	@Test
	public void unknownKillCountLeavesNothingBehind()
	{
		List<Stack> drop = Collections.singletonList(WHIP);
		assertEquals("from Vorkath, done", Template.render("from $source$kc, done", LootNotifier.placeholders(drop, drop, "Vorkath", null)));
	}

	@Test
	public void lootChestListsItsBestStackWhenTheWholeChestIsWorthIt()
	{
		List<Stack> chest = Arrays.asList(new Stack("Shark", 50, 800), new Stack("Rune platebody", 1, 38_000), new Stack("Coins", 30_000, 1));
		assertEquals(Collections.singletonList(chest.get(0)), LootNotifier.lootChestStandIn(chest, 100_000));
		assertTrue(LootNotifier.lootChestStandIn(chest, 200_000).isEmpty());
		assertTrue(LootNotifier.lootChestStandIn(Collections.emptyList(), 0).isEmpty());
	}

	@Test
	public void itemBasisComparesThePriceOfOne()
	{
		assertTrue(qualifying(Collections.singletonList(ONYX_TIPS), LootValueBasis.ITEM, 100_000, "", "").isEmpty());
		assertEquals(Collections.singletonList(WHIP), qualifying(Arrays.asList(WHIP, ONYX_TIPS), LootValueBasis.ITEM, 100_000, "", ""));
	}

	@Test
	public void stackBasisComparesPriceTimesQuantity()
	{
		assertEquals(Collections.singletonList(ONYX_TIPS), qualifying(Collections.singletonList(ONYX_TIPS), LootValueBasis.STACK, 100_000, "", ""));
	}

	@Test
	public void dropBasisAddsEverythingUpAndListsIt()
	{
		List<Stack> drop = Arrays.asList(new Stack("Shark", 50, 800), new Stack("Coins", 70_000, 1));
		assertEquals(drop, qualifying(drop, LootValueBasis.DROP, 100_000, "", ""));
		assertTrue(qualifying(drop, LootValueBasis.DROP, 110_001, "", "").isEmpty());
	}

	@Test
	public void deniedStacksDontCountTowardTheDrop()
	{
		List<Stack> drop = Arrays.asList(ONYX_TIPS, LAWS);
		assertTrue(qualifying(drop, LootValueBasis.DROP, 100_000, "", "Onyx bolt tips").isEmpty());
		assertEquals(Collections.singletonList(LAWS), qualifying(drop, LootValueBasis.DROP, 1_000, "", "onyx*"));
	}

	@Test
	public void denylistBlocksAValuableStack()
	{
		assertTrue(qualifying(Collections.singletonList(ONYX_TIPS), LootValueBasis.STACK, 100_000, "", "Onyx bolt tips").isEmpty());
	}

	@Test
	public void denylistWinsOverAllowlist()
	{
		assertTrue(qualifying(Collections.singletonList(ONYX_TIPS), LootValueBasis.STACK, 100_000, "Onyx*", "*bolt tips").isEmpty());
	}

	@Test
	public void allowlistIgnoresPriceOnEveryBasis()
	{
		Stack shadow = new Stack("Tumeken's shadow (uncharged)", 1, 0);
		for (LootValueBasis basis : LootValueBasis.values())
		{
			assertEquals(Collections.singletonList(shadow), qualifying(Arrays.asList(shadow, LAWS), basis, 100_000, "Tumeken's shadow*", ""));
		}
	}

	@Test
	public void singleItemChatDropGetsThroughTheAllowlist()
	{
		Stack marlin = new Stack("Swift marlin", 1, 6_000);
		List<Stack> drop = Collections.singletonList(marlin);
		assertTrue(qualifying(drop, LootValueBasis.STACK, 100_000, "", "").isEmpty());
		assertEquals(drop, LootNotifier.qualifying(drop, "Deep sea trawling", 100_000, LootValueBasis.STACK, WildcardList.parse("Swift marlin"), WildcardList.parse("")));
	}

	@Test
	public void lootChestFallbackOnlyAppliesToItemAndStack()
	{
		assertEquals(Collections.singletonList(CHEST.get(0)), chestQualifying(LootValueBasis.ITEM, 100_000, ""));
		assertEquals(Collections.singletonList(CHEST.get(0)), chestQualifying(LootValueBasis.STACK, 100_000, ""));
		assertEquals(CHEST, chestQualifying(LootValueBasis.DROP, 100_000, ""));
		assertTrue(chestQualifying(LootValueBasis.DROP, 200_000, "").isEmpty());
	}

	@Test
	public void lootChestFallbackNeverPicksADeniedStack()
	{
		assertEquals(Collections.singletonList(CHEST.get(1)), chestQualifying(LootValueBasis.STACK, 60_000, "Shark"));
		assertTrue(chestQualifying(LootValueBasis.STACK, 100_000, "Shark").isEmpty());
	}

	@Test
	public void chatDropsCoverSceptreAndTrawling()
	{
		assertEquals("Pyramid Plunder", LootNotifier.CHAT_DROPS.get("You have found a Pharaoh's sceptre! It fell on the floor.").getSource());
		assertEquals("Deep sea trawling", LootNotifier.CHAT_DROPS.get("You catch a swift marlin!").getSource());
	}

	@Test
	public void skipsGamblesAndClueCaskets()
	{
		assertTrue(LootNotifier.isSkippedEvent("Barbarian Assault high gamble"));
		assertTrue(LootNotifier.isSkippedEvent("Clue Scroll (Master)"));
		assertTrue(LootNotifier.isSkippedEvent("clue scroll (easy)"));
		assertFalse(LootNotifier.isSkippedEvent("Chambers of Xeric"));
		assertFalse(LootNotifier.isSkippedEvent("Clue"));
		assertFalse(LootNotifier.isSkippedEvent(null));
	}

	@Test
	public void deniedSourcesMatchIgnoringCaseAndWithWildcards()
	{
		WildcardList denylist = WildcardList.parse("barrows\n*Tempoross*");
		assertTrue(LootNotifier.isDeniedSource("Barrows", LootRecordType.EVENT, denylist));
		assertTrue(LootNotifier.isDeniedSource("Reward pool (Tempoross)", LootRecordType.EVENT, denylist));
		assertFalse(LootNotifier.isDeniedSource("Vorkath", LootRecordType.NPC, denylist));
	}

	@Test
	public void sourceDenylistIgnoresPlayers()
	{
		WildcardList denylist = WildcardList.parse("Zezima");
		assertFalse(LootNotifier.isDeniedSource("Zezima", LootRecordType.PLAYER, denylist));
		assertTrue(LootNotifier.isDeniedSource("Zezima", LootRecordType.NPC, denylist));
	}

	@Test
	public void deniedSourceIsMatchedWithoutTags()
	{
		assertTrue(LootNotifier.isDeniedSource("<col=ff0000>Vorkath</col>", LootRecordType.NPC, WildcardList.parse("Vorkath")));
	}

	@Test
	public void emptySourceDenylistDeniesNothing()
	{
		assertFalse(LootNotifier.isDeniedSource("Vorkath", LootRecordType.NPC, WildcardList.parse("")));
	}

	@Test
	public void missingSourceIsNotAnError()
	{
		assertFalse(LootNotifier.isDeniedSource(null, LootRecordType.NPC, WildcardList.parse("Vorkath")));
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.DiscordNotificationsConfig;
import com.discordnotifications.DiscordWebhookService;
import com.discordnotifications.KillCountService;
import com.discordnotifications.Notification;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldType;
import net.runelite.http.api.loottracker.LootRecordType;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import java.time.Instant;
import java.util.Collections;
import java.util.EnumSet;
import java.util.regex.Matcher;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class PetNotifierTest
{
	private static final String FOLLOWED = "You have a funny feeling like you're being followed.";
	private static final String WOULD_HAVE_BEEN = "You have a funny feeling like you would have been followed...";
	private static final String TEMPLATE = "$name got $pet$from$kc";
	private static final int WAIT_TICKS = 6;

	@Mock
	private Client client;

	@Mock
	private DiscordNotificationsConfig config;

	@Mock
	private DiscordWebhookService webhookService;

	@Mock
	private HeldNotifications heldNotifications;

	@Mock
	private KillCountService killCountService;

	@Mock
	private Player player;

	@InjectMocks
	private PetNotifier notifier;

	@Before
	public void setUp()
	{
		lenient().when(client.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
		lenient().when(client.getLocalPlayer()).thenReturn(player);
		lenient().when(player.getName()).thenReturn("Bob");
		lenient().when(config.includePets()).thenReturn(true);
		lenient().when(config.petMessage()).thenReturn(TEMPLATE);
	}

	private void play(String... messages)
	{
		for (String message : messages)
		{
			notifier.onGameMessage(message);
		}
		for (int i = 0; i < WAIT_TICKS; i++)
		{
			notifier.onGameTick();
		}
	}

	private Notification posted()
	{
		ArgumentCaptor<Notification> sent = ArgumentCaptor.forClass(Notification.class);
		verify(webhookService).send(sent.capture());
		return sent.getValue();
	}

	@Test
	public void knownNameUsesTheTemplate()
	{
		play(FOLLOWED, "Untradeable drop: Olmlet");
		assertEquals("Bob got Olmlet", posted().getText());
		assertNull(posted().getNamedText());
	}

	@Test
	public void noNameFallsBackAndLeavesTheTemplateForTheQueue()
	{
		play(FOLLOWED);
		assertEquals("Bob just got a pet!", posted().getText());
		assertEquals(TEMPLATE, posted().getNamedText());
	}

	@Test
	public void fallbackKeepsSourceAndKc()
	{
		when(killCountService.getRecentPetDrop()).thenReturn(new KillCountService.Drop("Zulrah", LootRecordType.NPC, Collections.emptyList(), Instant.now()));
		when(killCountService.getKillCount(LootRecordType.NPC, "Zulrah")).thenReturn(50);
		play(FOLLOWED);
		assertEquals("Bob just got a pet from Zulrah (KC 50)!", posted().getText());
	}

	@Test
	public void templateThatDoesntNeedTheNameIsKept()
	{
		when(config.petMessage()).thenReturn("$name got a pet!");
		play(FOLLOWED);
		assertEquals("Bob got a pet!", posted().getText());
		assertEquals("$name got a pet!", posted().getNamedText());
	}

	@Test
	public void duplicateNeverWaitsOnACollectionLogName()
	{
		when(config.notifyDuplicatePets()).thenReturn(true);
		play(WOULD_HAVE_BEEN);
		assertEquals("Bob just got a pet! (would have been followed)", posted().getText());
		assertNull(posted().getNamedText());
	}

	@Test
	public void duplicatesAreSkippedWhenTurnedOff()
	{
		play(WOULD_HAVE_BEEN, "Untradeable drop: Olmlet");
		verify(webhookService, never()).send(any());
	}

	private static Matcher clan(String message)
	{
		Matcher matcher = PetNotifier.CLAN_REGEX.matcher(message);
		assertTrue(message, matcher.find());
		return matcher;
	}

	@Test
	public void petMessages()
	{
		assertTrue(PetNotifier.PET_REGEX.matcher("You have a funny feeling like you're being followed.").matches());
		assertTrue(PetNotifier.PET_REGEX.matcher("You feel something weird sneaking into your backpack.").matches());
		assertTrue(PetNotifier.PET_REGEX.matcher("You have a funny feeling like you would have been followed...").matches());
		assertFalse(PetNotifier.PET_REGEX.matcher("You feel Forsen's warmth behind you.").matches());
	}

	@Test
	public void clanBroadcastWithMilestone()
	{
		Matcher matcher = clan("[Some Clan] Zezima has a funny feeling like he would have been followed: Olmlet at 1,234 kills.");
		assertEquals("Zezima", matcher.group("user").trim());
		assertEquals("Olmlet", matcher.group("pet"));
		assertEquals("1,234 kills", matcher.group("milestone"));
	}

	@Test
	public void clanBroadcastWithoutMilestone()
	{
		Matcher matcher = clan("Zezima feels like she's acquired something special: Yami");
		assertEquals("Yami", matcher.group("pet"));
		assertNull(matcher.group("milestone"));
	}

	@Test
	public void clanBroadcastKeepsSpacesAndHyphensInName()
	{
		assertEquals("Iron-Man Bob", clan("Iron-Man Bob feels something weird sneaking into his backpack: Heron at 5,000,000 XP.").group("user").trim());
	}

	@Test
	public void clanBroadcastKeepsPetNameFullStopBeforeMilestone()
	{
		assertEquals("Vet'ion jr.", clan("Bob has a funny feeling like she's being followed: Vet'ion jr. at 50 kills.").group("pet"));
	}

	@Test
	public void namesPetFromUntradeableAndCollectionLogChat()
	{
		assertEquals("Olmlet", PetNotifier.parsePetName("Untradeable drop: Olmlet"));
		assertEquals("Pet snakeling", PetNotifier.parsePetName("New item added to your collection log: Pet snakeling"));
	}

	@Test
	public void ignoresItemsThatArentPets()
	{
		assertNull(PetNotifier.parsePetName("Untradeable drop: Ensouled dragon head"));
		assertNull(PetNotifier.parsePetName("New item added to your collection log: Abyssal whip"));
		assertNull(PetNotifier.parsePetName("random unrelated chat message"));
	}
}

package com.discordnotifications.notifiers;

import com.discordnotifications.Template;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class QuestNotifierTest
{
	private static String parse(String text)
	{
		return QuestNotifier.parseQuestCompletedWidget(text);
	}

	@Test
	public void parsesRecipeForDisaster()
	{
		assertEquals("Recipe for Disaster - Another Cook's Quest", parse("You have completed Another Cook's Quest!"));
		assertEquals("Recipe for Disaster - Another Cook's Quest", parse("You have assisted the Lumbridge Cook... again!"));
		assertEquals("Recipe for Disaster - Goblin Generals", parse("You have freed the Goblin Generals!"));
		assertEquals("Recipe for Disaster - Sir Amik Varze", parse("You have freed Sir Amik Varze!"));
		assertEquals("Recipe for Disaster - Skrach Uglogwee", parse("You have freed Skrach 'Bone Crusher' Uglogwee!"));
		assertEquals("Recipe for Disaster", parse("You have completed Recipe for Disaster!"));
	}

	@Test
	public void keepsQuestInNamesThatHaveIt()
	{
		assertEquals("Doric's Quest", parse("You have completed Doric's Quest!"));
		assertEquals("Heroes Quest", parse("You have completed the Heroes' Quest!"));
	}

	@Test
	public void parsesNumberedQuests()
	{
		assertEquals("Dragon Slayer I", parse("You have completed the Dragon Slayer I quest!"));
		assertEquals("Dragon Slayer II", parse("You have completed Dragon Slayer II!"));
		assertEquals("Rag and Bone Man II", parse("You have completed Rag and Bone Man II!"));
		assertEquals("Fairytale II - Cure a Queen", parse("You have completed Fairytale II - Cure a Queen!"));
	}

	@Test
	public void skipsPartialCompletion()
	{
		assertNull(parse("You have... kind of... completed Hazeel Cult!"));
		assertEquals("Hazeel Cult", parse("You have completed Hazeel Cult!"));
	}

	@Test
	public void fallsBackToTitleWhenNothingMatches()
	{
		assertEquals("Congratulations on finishing Some New Quest!", parse("Congratulations on finishing Some New Quest!"));
		assertNull(parse(""));
	}

	@Test
	public void rendersPlaceholders()
	{
		assertEquals("Cook's Assistant 22/156 44/293",
			Template.render("$quest $completed/$totalQuests $qp/$qpMax", QuestNotifier.placeholders("Cook's Assistant", 22, 156, 44, 293)));
	}

	@Test
	public void progressAddsItsOwnSpace()
	{
		assertEquals("Cook's Assistant (44/293 QP)",
			Template.render("$quest$progress", QuestNotifier.placeholders("Cook's Assistant", 22, 156, 44, 293)));
	}

	@Test
	public void progressIsBlankWhenUnknown()
	{
		assertEquals("Cook's Assistant",
			Template.render("$quest$progress", QuestNotifier.placeholders("Cook's Assistant", 22, 156, 0, 293)));
	}

	@Test
	public void leavesNumbersBlankWhenUnknown()
	{
		assertEquals("Cook's Assistant / 44/293",
			Template.render("$quest $completed/$totalQuests $qp/$qpMax", QuestNotifier.placeholders("Cook's Assistant", 0, 156, 44, 293)));
		assertEquals("Cook's Assistant 22/156 /",
			Template.render("$quest $completed/$totalQuests $qp/$qpMax", QuestNotifier.placeholders("Cook's Assistant", 22, 156, 44, 0)));
	}
}
